SELECT 'moj-all-verified-judgments-review-002-chunk-093' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"dbfe6176-edb7-510a-9f28-fd78b7feb15e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر - إقرار -إدانة -التعزير بالسجن .","document_number":"33394061","case_number":"33543638","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف أنه لم يتم تطبيق املواد املنظمة إليداع املدمن يف مصحة للعاج قبل احلكم بذلك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/08/24","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر - إقرار -إدانة -التعزير بالسجن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33394061:‬تاريخه‪1433/08/24:‬هـ‬\n                         ‫رقم الدعوى‪33543638:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪3441617‬تاريخه‪1434/02/19:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬حــد املســكر ‪-‬‬\n                                            ‫إقــرار‪ -‬إدانــة ‪ -‬التعزيــر بالســجن ‪.‬‬\n\n\n\n\n                                                     ‫‪ -1‬اإلقرار حجة على املقر‪.‬‬\n                                                              ‫‪ -2‬ال عذر ملن أقر‪.‬‬\n      ‫‪ -3‬املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬واملــادة (‪ )43‬مــن نظــام‬\n                                     ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n      ‫‪ -4‬الفقــرة (أ) مــن الفقــرة (‪ )2‬والفقــرات (‪ )6،7‬مــن املــادة الثانيــة‬\n      ‫والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات واملؤثرات‬\n                                                                        ‫العقليــة‪.‬‬\n      ‫‪ -5‬توجيه وكيل الوزارة للشؤون القضائية ذي الرقم ‪.27/36420/28‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي وتعاطيــه لــه ‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع‬\n      ‫مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n      ‫حيــث إنــه مت تفتيــش الســيارة التــي يقودهــا املدعــى عليــه فعثــر فيــه علــى‬\n      ‫ســيجارة مــن احلشــيش املخــدر‪ ،‬وأثبــت التقريــر الكيمــاوي الشــرعي‬\n\n‫‪177‬‬\n\f‫احتــواء العينــة املرســلة علــى احلشــيش املخــدر وأقــر املدعــى عليــه أمــام‬\n‫احملكمــة مبــا أســنده إليــه املدعــي العــام وأعلــن ندمــه وطلــب عالجــه‬\n‫مــن اإلدمــان‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بجميــع مــا نســب إليــه وقــررت جلــده ثمانــن جلــدة دفعــة واحــدة‬\n‫حــد املســكر علنـاً‪ ،‬كمــا أمــرت بإيداعــه ملــدة ســتة أشــهر يف مصحــة‬\n‫مخصصــة لعــاج املدمنــن وأفهمتــه مبنعــه مــن الســفر خــارج اململكــة‬\n‫ملــدة ســنتني‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪،‬‬\n‫والحظــت محكمــة االســتئناف أنــه لــم يتــم تطبيــق املــواد املنظمــة إليــداع‬\n‫املدمــن يف مصحــة للعــاج قبــل احلكــم بذلــك‪ ،‬ورجعــت احملكمــة عمــا‬\n‫حكمــت بــه يف الفقــرة (الثانيــة) وقــررت أخيــر ًا ســجن املدعــى عليــه‬\n‫ســتة أشــهر‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪،‬‬\n                    ‫وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا القاضــي باحملكمــة اجلزئيــة بالقطيــف‬\n‫بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم ‪ ........‬يف‬\n‫‪1433/8/24‬ه ـ والــواردة بكتــاب رئيــس دائــرة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة القطيــف بكتابــه ذي الرقــم ه ـ ق‪ 2374/2/4‬يف‬\n‫‪1433/8/21‬ه ـ حضــر املدعــي العــام مبوجــب كتــاب التكليــف رقــم‬\n‫‪ ........‬يف ‪1431/9/15‬ه ـ وادعــى علــى احلاضــر معــه ‪ ........‬بالســجل‬\n‫ا يف دعــواه إنــه بتاريــخ ‪1433/7/10‬ه ـ مت‬       ‫املدنــي رقــم ‪ ........‬قائ ـ ً‬\n‫القبــض علــى املدعــى عليــه أثنــاء قيــام الدوريــات األمنيــة بالدمــام‬\n‫بواجبهــا عنــد نقطــة التفتيــش بعــد اســتيقاف مركبتــه وبتفتيشــها‬\n\n                                                                                    ‫‪178‬‬\n\f      ‫عثــر علــى ســيجارة بلــغ وزنهــا (‪ )1.2‬جــرام واحــد واثنــان مــن العشــرة‬\n      ‫مــن اجلــرام بــن املرتبتــن أثبــت التقريــر الكيمــاوي الشــرعي الصــادر‬\n      ‫مــن املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية رقــم (‪)........‬‬\n      ‫‪1433/7/14‬ه ـ احتوائهــا ملــادة احلشــيش املخــدرة واحملظــورة وقــد انتهى‬\n      ‫التحقيــق معــه إلــى توجيــه االتهــام إليــه بحيــازة ســيجارة بلــغ وزنهــا (‪)1.2‬‬\n      ‫جــرام واحــد واثنــان مــن العشــرة مــن اجلــرام بقصــد التعاطــي وتعاطيــه‬\n      ‫لنوعهــا وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى ثــاث ســوابق‬\n      ‫ســابقتي حيــازة واســتعمال مخــدرات وســابقة ســرقة وحيــث أن مــا أقــدم‬\n      ‫عليــه املذكــور ‪-‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا اطلــب إثبــات مــا اســند إليــه وفق ـ ًا‬\n      ‫للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪-1 :‬بعقوبــة الســجن الــواردة‬\n      ‫بالفقــرة (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام املشــار إليــه ‪-2‬منعــه مــن‬\n      ‫الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام املشــار إليــه‬\n      ‫ال‬‫هــذا مــا ادعــى بــه وبعرضــه علــى املدعــى عليــه وبســؤاله عنه أجــاب قائ ً‬\n      ‫مــا ذكــره املدعــي العــام يف دعــواه ضــدي مــن اتهامــي بحيــازة مــا ذكــر‬\n      ‫لغــرض التعاطــي وقيامــي بتعاطــي احلشــيش املخــدر كلــه صحيــح وأنــا‬\n      ‫نــادم علــى مــا اقترفــت وأطلــب عالجــي مــن ممــا ابتليــت بــه وقــد ذهبــت‬\n      ‫لغــرض العــاج إال أنــه مت االعتــذار مــن اســتقبال حالتــي لوجــود حــاالت‬\n      ‫مقدمــة هــذا مــا أجــاب بــه وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n      ‫الشــرعي رقــم (‪ )........‬وتاريــخ ‪1433/7/14‬ه ـ املرفــق باملعاملــة باللفــة‬\n      ‫رقــم (‪ )14‬وتبــن مطابقتــه ملــا عطــف عليــه املدعــي العــام فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه مبــا نســبه لــه املدعــي‬\n\n\n‫‪179‬‬\n\f‫العــام وألن اإلقــرار حجــة علــى املقــر وال عــذر ملــن أقــر وبنــاء علــى املــادة‬\n‫احلاديــة واألربعــن والسادســة واخلمســن مــن نظــام مكافحــة املخــدرات‬\n‫ولضآلــة الكميــة التــي حازهــا املدعــى عليــه وإلظهــاره للتوبــة والنــدم‬\n‫ولرغبتــه يف العــاج ولوجــود ســابقتني قريبتــن مــن جنــس القضيــة‬\n‫الالحقــة إذ مت احلكــم يف آخرهمــا بتاريــخ ‪1432/6/5‬ه ـ واحلكــم يف‬\n‫التــي قبلهــا بتاريــخ ‪1433/2/6‬ه ـ ممــا يفيــد عــدم ارتــداع املدعــى عليــه‬\n‫مبــا مت احلكــم عليــه بــه ممــا يتجــه معــه التشــديد يف العقوبــة وعــدم‬\n‫انتفاعــه باملــادة الســتني مــن نظــام مكافحــة املخــدرات وبنــاء علــى‬\n‫املــادة الثالثــة واألربعــن منــه وبنــاء علــى الفقــرة (أ) مــن الفقــرة الثانيــة‬\n‫مــن املــادة الثانيــة والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة‬\n‫املخــدرات وبنــاء علــى توجيــه وكيــل الــوزارة للشــؤون القضائيــة ذي‬\n‫الرقــم ‪ 27/36420/28‬والــذي يتضمــن أنــه ينبغــي للقاضــي بعــد تقريــر‬\n‫العقوبــة األصليــة إفهــام احملكــوم عليــه مبقتضاهــا وينــص علــى ذلــك‬\n‫يف الضبــط والقــرار لــذا وجلميــع مــا تقــدم فقــد ثبــت لــدي حيــازة املدعــى‬\n‫عليــه للكميــة املوصوفــة يف الدعــوى وقيامــه بتعاطــي احلشــيش املخــدر‬\n‫وقــررت أو ًال جلــد املدعــى عليــه ثمانــن جلــدة دفعــة واحــدة حــد املســكر‬\n‫علن ـ ًا ثاني ـ ًا األمــر بإيــداع املدعــى عليــه مــدة ســتة أشــهر يحتســب منهــا‬\n‫مــدة إيقافــه بســبب هــذه القضيــة يف مصحــة مخصصــة لعــاج املدمنــن‬\n‫يعالــج خاللهــا مــن إدمانــه بنــاء علــى الفقــرة السادســة والســابعة من املادة‬\n‫الثانيــة والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n‫بعــد التحقــق مــن إدمانــه بتقريــر طبــي يصــدر مــن مصحــة مخصصــة‬\n‫لهــذا الغــرض بنــاء علــى الفقــرة األولــى مــن املــادة الثانيــة والثالثــن مــن‬\n‫الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات فــإن بــان عــدم إدمانــه‬\n\n\n                                                                                          ‫‪180‬‬\n\f      ‫فيوقــع علــى املدعــى عليــه عقوبــة الســجن بــذات املــدة املقــررة لإليــداع‬\n      ‫يف املصحــة محتســب منهــا مــدة إيقافــه بســبب هــذه القضيــة ومبــا‬\n      ‫ذكــر حكمــت وأفهمــت املدعــى عليــه مبضمــون الفقــرة األولــى مــن‬\n      ‫املــادة السادســة واخلمســن مــن نظــام مكافحــة املخــدرات مبنعــه مــن‬\n      ‫الســفر مــدة ســنتني تبــدأ بعــد إنهــاء محكوميتــه وأن لوزيــر الداخليــة‬\n      ‫اإلذن بالســفر أثنــاء مــدة املنــع للضــرورة ففهــم ذلــك وبعــرض احلكــم‬\n      ‫علــى الطرفــن اعتــرض عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي‬\n      ‫الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه وســيتم بعــث املعاملــة حملكمــة‬\n      ‫االســتئناف بالدمــام لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف‬\n      ‫‪1433/8/26‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                             ‫أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية بكتــاب فضيلــة رئيســها رقــم ‪331656221‬‬\n      ‫يف ‪1433/11/24‬ه ـ املقيــدة يف هــذه احملكمــة برقــم ‪ ........‬يف‬\n      ‫‪1433/11/28‬ه ـ واحملالــة مــن فضيلــة الرئيــس وبرفقهــا القــرار الصادر‬\n      ‫مــن أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى رقــم ‪ ........‬يف‬\n      ‫‪1433/11/15‬ه ـ ونصــه بعــد املقدمــة وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة لوحــظ أن فضيلــة ناظــر القضيــة حكــم بإيــداع املدعــى‬\n      ‫عليــه باملصحــة ولــم يطبــق مقتضــى الفقــرة األولــى مــن املــادة الثانيــة‬\n      ‫والثالثــن ومــا بعدهــا ومــا قــرره فضيلتــه ســابق ألوانــه ملالحظــة مــا‬\n      ‫ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1433/11/14‬ه ـ قاضي‬\n      ‫اســتئناف ‪ ........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه‬\n\n\n‫‪181‬‬\n\f‫رئيــس الدائــرة ختمــه وتوقيعــه أ‪.‬ه ـ وأجيــب أصحــاب الفضيلــة وفقنــي‬\n‫اهلل وإياهــم إلصابــة الصــواب بأنــه جــرى األمــر بتطبيــق الفقــرة األولــى‬\n‫مــن املــادة الثانيــة والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة‬\n‫املخــدرات كمــا هــو ظاهــر مــن الفقــرة الثانيــة مــن منطــوق احلكــم‬\n‫هــذا مــا لــزم جوابـ ًا علــى مالحظــة أصحــاب الفضيلــة ولفضيلتهــم فائــق‬\n‫التقديــر واالحتــرام وللبيــان حــرر يف ‪1434/1/6‬ه ـ وصلــى اهلل وســلم‬\n                          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية بكتــاب فضيلــة رئيســها رقــم يف ‪1434/2/26‬ه ـ‬\n‫املقيــدة يف هــذه احملكمــة برقــم ‪ 34532790‬يف ‪1434/3/1‬ه ـ واحملالــة‬\n‫مــن فضيلــة الرئيــس وبرفقهــا القــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة اجلزائيــة األولى رقم ‪ 3441617‬يف ‪1434/2/19‬هـ ونصه‬\n‫بعــد املقدمــة حيــث ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪/33455414‬ج‪/1‬ب يف ‪1433/11/15‬ه ـ لوحــظ أن تطبيــق‬\n‫املــادة املشــار إليهــا يكــون بعــد التحقيــق مــن إدمــان املدعــى عليــه بتقرير‬\n‫طبــي وهــذا لــم يكمــل الزمــه فضيلتــه ملالحظــة مــا ذكــر وإكمــال‬\n‫الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمد‬\n‫وآلــه وصحبــه وســلم حــرر يف ‪1434/2/17‬ه ـ قاضــي اســتئناف ‪........‬‬\n‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫‪ ........‬ختمــه وتوقيعــه أ‪.‬ه ـ عليــه فقــد حضــر املدعــي العــام واملدعــى‬\n‫عليــه وبســؤال املدعــى عليــه عــن كيفيــة القبــض عليــه وهــل كان بنــاء‬\n‫ا لقــد ألقــي القبــض علــي يف‬  ‫علــى بــاغ أو شــكوى ضــده أجــاب قائ ـ ً‬\n\n\n                                                                                       ‫‪182‬‬\n\f      ‫نقطــة التفتيــش ولــم يســبقه شــكوى أو بــاغ ضــدي هــذا مــا أجــاب بــه‬\n      ‫وبالرجــوع إلــى الئحــة نظــام املخــدرات وتأملهــا بنــاء علــى الفقــرة (ج) مــن‬\n      ‫الفقــرة الثانيــة مــن املــادة الثانيــة والثالثــن مــن الئحــة نظــام مكافحــة‬\n      ‫املخــدرات والتــي تتضمــن أن املدمــن مــن تضبطــه اجلهــات املختصــة بنــاء‬\n      ‫علــى شــكوى أو بــاغ لــذا وملــا تقــدم فقــد رجعــت عــن الفقــرة الثانيــة‬\n      ‫مــن منطــوق احلكــم وقــررت ســجن املدعــى عليــه ســتة أشــهر يحتســب‬\n      ‫منهــا مــدة إيقافــه بســبب هــذه القضيــة وبــه حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن اعتــرض عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي‬\n      ‫الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه وســيتم بعــث كامــل املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف‬\n      ‫‪1434/5/1‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                ‫أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالدمــام بكتــاب فضيلــة رئيســها رقــم ‪ 341171418‬يف ‪1434/6/20‬هـ‬\n      ‫املقيــدة يف هــذه احملكمــة برقــم ‪ 341171418‬يف ‪1434/6/24‬ه ـ‬\n      ‫واحملالــة مــن فضيلــة الرئيــس وبرفقهــا إعــام احلكــم الصــادر مني برقم‬\n      ‫‪ 33394061‬يف ‪1433/8/26‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلة قضاة‬\n      ‫الدائــرة اجلزائيــة األولــى رقــم ‪ 34238210‬يف ‪1434/6/12‬ه ـ ونصــه‬\n      ‫بعــد املقدمــة حيــث ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم ‪ 3441617‬يف ‪1434/2/19‬ه ـ قررنــا املصادقــة علــى‬\n      ‫احلكــم بعــد االجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/6/11‬ه ـ قاضــي اســتئناف ‪........‬‬\n\n\n‫‪183‬‬\n\f‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫‪ ........‬ختمــه وتوقيعــه أ‪.‬ه ـ وللبيــان حــرر يف ‪1434/6/24‬ه ـ وصلــى اهلل‬\n                  ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                               ‫‪184‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":177,"source_page_end":184,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"860d300133cf510b41034034a1def271995c10d223e876d2b7f3c8b2cd66e00f","normalized_text_hash":"80f587442b18167b074fe16e6a6b65bf4eb387760550c6a41f44137205f979d0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p177-33394061"},{"id":"b9d36ad3-07e6-5030-84fc-012e18687977","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي -قات -ضآلة الكمية املضبوطة -التعزير بالسجن و اإلبعاد عن الباد .","document_number":"3441034","case_number":"33574679","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/19","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي -قات -ضآلة الكمية املضبوطة -التعزير بالسجن و اإلبعاد عن الباد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪3441034:‬ىتاريخه‪1434/2/19:‬هـ‬\n                        ‫رقم الدعوى‪33574679:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3460557‬تاريخه‪1434/03/11:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي ‪ -‬قــات ‪ -‬ضآلــة الكميــة املضبوطــة‬\n                                   ‫‪ -‬التعزيــر بالســجن و اإلبعــاد عــن البــاد ‪.‬‬\n\n\n\n\n                              ‫‪ -1‬املادة ‪ 159‬من نظام اإلجراءات اجلزائية ‪.‬‬\n      ‫‪-2‬الفقــرة األولــى مــن األمــر الســامي الكــرمي رقــم (‪ )59633‬يف‬\n                                                       ‫‪1432 /12 /9‬هــ‪.‬‬\n      ‫‪ -3‬املادة الرابعة من قرار وزير الداخلية رقم ( ‪ ) 2057‬يف ‪1404/5/26‬هـ‪.‬‬\n                    ‫‪ -4‬قرار وزير الداخلية رقم (‪ )3818‬يف ‪1410/9/28‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد االســتعمال‬\n      ‫الشــخصي وتســتره علــى مصــدر مــا مت ضبطــه و طلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم بتعزيــره وفــق املــادة الرابعــة مــن قــرار مجلــس الــوزراء‬\n      ‫رقــم(‪ )11‬لعــام ‪1374‬ه وتشــديد العقوبــة لقــاء تســتره و حيــث مت القبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل فرقــة مكافحــة املخــدرات وبتفتيشــه عثــر‬\n      ‫بحوزتــه كميــة مــن نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى عليــه‬\n      ‫علــى االدعــاء املوجــه إليــه بحيــازة القــات بقصــد االســتعمال الشــخصي‪،‬‬\n\n‫‪185‬‬\n\f‫ونظــر ًا لعــدم وجــود ســوابق عليــه ولضآلــة مــا ضبــط بحوزتــه حكمــت‬\n‫احملكمــة بتعزيــره بالســجن مــدة شــهر ونصــف وإبعــاده إلــى بــاده بعــد‬\n‫انتهــاء محكوميتــه وصــرف النظــر عــن طلــب املدعــي العــام تشــديد‬\n‫العقوبــة علــى املدعــى عليــه لقــاء اتهامــه بالتســتر ألن ذلــك مندفــع مبــا‬\n‫علــم مــن بائعــي القــات مــن تخفيهــم وتنكرهــم وقنــع املدعــى عليــه‬\n‫باحلكــم واعتــرض املدعــي العــام بــدون الئحــة و صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )331703298‬وتاريــخ ‪1433/9/13‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )33574679‬وتاريخ ‪1433/9/13‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬املتهــم يف قضيــة قــات وقــد‬\n‫أعيــدت لعرضهــا علــى اللجنــة املكلفــة بتطبيــق تعليمــات العفــو بخطابنا‬\n‫رقــم (‪ )331703298‬وتاريــخ ‪1433/9/18‬ه ـ وأعيــدت متضمنــة عــرض‬\n‫املدعــى عليــه علــى اللجنــة املذكــورة وتقريرهــا عــدم شــموله بالعفــو‬\n‫كمــا دون علــى اللفتــن (‪ )34،33‬عليــه ففــي هــذا اليــوم األحــد‬\n‫‪1434/2/17‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة الثانيــة عشــرة‬\n‫اال ربعــا وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم (‪).....‬‬\n‫وتاريــخ ‪1433/3/22‬ه ـ وادعــى علــى احلاضر‪.....‬مينــي اجلنســية يحمــل‬\n‫البطاقــة البديلــة رقــم (‪ ).....‬يف ‪1433/8/19‬ه ـ الصــادرة مــن اإلدارة‬\n‫العامــة ملكافحــة املخــدرات أنــه بتاريــخ ‪1433/8/19‬ه ـ وأثنــاء قيــام‬\n\n                                                                                      ‫‪186‬‬\n\f      ‫أفــراد مكافحــة املخــدرات بواجبهــم امليدانــي يف قريــة ‪.....‬مت القبــض‬\n      ‫علــى املدعــى عليــه وبتفتيشــه عثــر معــه علــى كميــة مــن نبــات القــات‬\n      ‫احملظــور بلــغ وزنهــا (‪149‬ج ــم) مائــة وتســعة وأربعــن جرامــا واملثبتــة‬\n      ‫بالتقريــر الكيميائــي الشــرعي رقــم (‪.....‬للعــام ‪1433‬هــ) الصــادر‬\n      ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بجــازان‬\n      ‫(وبرفقتــه ‪.....‬أفــرج عنــه ولــم يوجــه لــه االتهــام وأحيــل جلهــة االختصــاص‬\n      ‫لكونــه مقيمــا بطريقــه غيــر مشــروعه) ومبواجهــة املدعــى عليــه بالتهمة‬\n      ‫املنســوبة وبأقوالــه مبحضــر ســماع األقــوال أقــر بصحــة واقعــة القبــض‬\n      ‫وأن الكميــة املضبوطــة مــن نبــات القــات احملظــور عائــدة لــه وغرضــه‬\n      ‫منهــا االســتعمال الشــخصي وأنــه حصــل عليهــا بالشــراء مــن شــخص‬\n      ‫ال يعرفــه وصــادق علــى أقوالــه حتقيقــا وبالبحــث عــن ســوابقه لــم يعثــر‬\n      ‫لــه علــى ســوابق مســجلة حتــى تاريخــه وقــد أســفر التحقيــق معــه عــن‬\n      ‫توجيــه االتهــام إليــه بحيــازة الكميــة املضبوطــة مــن نبــات القــات بقصــد‬\n      ‫االســتعمال الشــخصي وتســتره على مصدر ما مت ضبطه وطلب املدعي‬\n      ‫العــام إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره اســتناد ًا إلــى املــادة‬\n      ‫الرابعــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ وتشــديد‬\n      ‫العقوبــة عليــه لقــاء تســتره علــى مصــدر مــا مت ضبطــه وبعــرض دعــوى‬\n      ‫املدعــي العــام علــى املدعــى عليــه صــدق مــا جــاء فيهــا جملــة وتفصيــا‬\n      ‫وقــرر أنــه حصــل علــى كميــة القــات املضبوطــة مــن شــخص مينــي ال‬\n      ‫يعرفــه بقريــة ‪.....‬مقابــل خمســن ريــا ًال هكــذا أجــاب وبالرجــوع إلــى‬\n      ‫أوراق املع ــاملة جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي وثبــت‬\n      ‫ســوابق املدعــى عليــه فوجــدت مطابقــة ملــا يف الدعــوى عليــه فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وملــا تضمنــه األمــر الســامي الكــرمي رقــم‬\n\n\n‫‪187‬‬\n\f‫(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ يف فقرتــه األولــى مــن املوافقــة على أن‬\n‫تطبــق احملاكــم علــى مرتكبــي جرائــم القــات العقوبــات املعمــول بهــا‬\n‫قبــل نفــاذ نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لذلــك كلــه‬\n‫فقــد ثبتــت لــدي إدانــة املدعــى عليــه بحيــازة كميــة القــات املذكــورة‬\n‫أعــاه بقصــد التعاطــي وهــو يســتحق العقوبــة علــى ذلــك يف ضــوء املــادة‬\n‫(‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ‬\n‫املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ ‪1410/9/28‬ه ـ ونظــرا‬\n‫لعــدم وجــود ســوابق مســجلة عليــه ولضآلــة مــا ضبــط بحوزتــه ولكــون‬\n‫املضبــوط مــن نبــات القــات واســتصالحا حلالــه فقــد حكمــت عليــه‬\n‫لذلــك بالســجن مــدة شــهر ونصــف تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه‬\n‫علــى ذمــة هــذه القضيــة يف ‪1433/8/19‬ه ـ وإبعــاده إلــى بــاده بعــد‬\n‫انتهــاء محكوميتــه بالســجن ونظــرا ألن املــادة املشــار إليهــا قــد جعلــت‬\n‫التعزيــر باجللــد إلــى نظــر القاضــي فقــد قــررت االكتفــاء عنــه بعقوبــة‬\n‫احلبــس واســتناد ًا إلــى املــادة (‪ )159‬مــن نظــام اإلجــراءات اجلزائيــة فقــد‬\n‫صرفــت النظــر عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه يف‬\n‫ضــوء املــادة الرابعــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n‫لعــدم دخــول االتهــام املذكــور أعــاه يف منطوقهــا كمــا صرفــت النظــر‬\n‫عــن طلــب املدعــي العــام تشــديد العقوبــة علــى املدعــى عليــه لقــاء اتهامــه‬\n‫بالتســتر علــى مصــدر مــا مت ضبطــه ألن ذلــك مندفــع مبــا علــم مــن حــال‬\n‫بائعــي نبــات القــات يف املنطقــة مــن تخفيهــم وتنكرهــم واســتغاللهم‬\n‫مجهولــي الهويــة لترويــج نبــات القــات وهــو أمــر عمــت بــه البلــوى هــذا‬\n‫مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي العــام‬\n‫معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون الئحــة فأجبتــه لذلــك‬\n\n\n                                                                                      ‫‪188‬‬\n\f      ‫وقــرر املدعــى عليــه القناعــة بــه وقــد جــرى النطــق بــه يف متــام الســاعة‬\n      ‫الثانيــة عشــرة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه أجمعــن حــرر يف ‪1434/2/17‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪3483829‬‬\n      ‫وتاريــخ‪1434/2/ 25‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪...../‬برقم‪ 3441034‬وتاريــخ ‪1434/2/19‬ه ـ اخلــاص بدعــوى‬\n      ‫املدعــي العــام ضــد ‪-..... /‬مينــي اجلنســية ‪ -‬يف قضيــة ( قــات ) علــى‬\n      ‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪189‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":185,"source_page_end":189,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0ced2f7be85dfdc7541d6ba9a5d563cc9a05ef40eaef06fe85d926ab8bbcd1f1","normalized_text_hash":"32b246c4a1e130434d983f8c62f3292c415726a7178d8030f11a8cf0d9ceacb6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p185-3441034"},{"id":"8f9b957b-9dcc-556d-a2ca-a33f127a4c62","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة -تداخل التعازير -التعزير بالسجن واجللد واملنع من السفر .","document_number":"33416641","case_number":"33577847","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/17","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة -تداخل التعازير -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33416641:‬تاريخه‪1433/09/17:‬هـ‬\n                   ‫رقم الدعوى‪33577847 :‬‬\n      ‫رقم قرار التصديق محكمة االستئناف‪:‬‬\n          ‫‪ 3440166‬تاريخه‪1433/02/18:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا‪ -‬إقــرار‪-‬‬\n‫عــدم التقيــد بالوصــف الــوارد يف الئحــة الدعــوى‪ -‬إدانــة‪ -‬تداخــل‬\n              ‫التعازيــر ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n                       ‫‪ -1‬املادة (‪ )159‬من نظام اإلجراءات اجلزائية‪.‬‬\n‫‪ -2‬املادتان (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي وتعاطيــه لهــا‪ ،‬واحلكــم عليــه‬\n‫بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة وتشــديد العقوبــة بحقــه لقــاء تكــرر ســوابقه‪ ،‬بعــد‬\n‫اســتيقافه قــام بابتــاع حبــوب يشــتبه يف كونهــا محظــورة كانــت يف‬\n‫كيــس بجيبــه وعثــر بالكيــس علــى فتــات مــن احلبــوب‪ ،‬أثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة اإلمفيتامــن‪ ،‬أقــر‬\n‫أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬بنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت‬\n‫ســجنه ملــدة ســتة أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‬\n\n                                                                                   ‫‪190‬‬\n\f      ‫وجلــده ســبعني جلــدة دفعــة واحــدة لقــاء تعاطيــه احلبــوب احملظــورة‬\n      ‫وجلــده ســبعني جلــدة لقــاء الســوابق املســجلة بحقــه‪ ،‬وقنــع املدعــى عليــه‬\n      ‫باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف‬\n                                                          ‫املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة ويف هــذا اليــوم‬\n      ‫الثالثــاء املوافــق ‪1433/9/19‬ه ـ يف متــام الســاعة الواحــدة ظهرا افتتحت‬\n      ‫اجللسة وفيها حضر املدعي العام ‪ ........‬سعودي اجلنسية بالسجل املدني‬\n      ‫رقــم ‪........‬واملعمــد مــن رئيــس هيئــة التحقيــق واالدعــاء العــام برقــم ‪........‬‬\n      ‫ويف ‪1432/6/12‬ه ـ قائــا يف حتريــر دعــواه ضد ‪ ........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪)..........‬انــه باالطــاع علــى احملضــر املدون‬\n      ‫بتاريــخ ‪1433/8/11‬ه ـ مــن قبــل مركــز هيئــة األمــر باملعــروف والنهــي‬\n      ‫عــن املنكــر بامليقــات املتضمــن انــه مت مالحظــة ســيارة ‪ ........‬وظهــر‬\n      ‫علــى الراكــب إثــر الريبــة ومحاولــة الهــروب ومت اســتيقافه واتضــح أنــه‬\n      ‫بحالــة غيــر طبيعيــة وأخــرج مــن جيبــة األميــن كيســا يشــتبه أن بــه حبوبــا‬\n      ‫محظــورة وقــام بابتالعهــا أمــام مــرأى الفرقــة وعثــر بالكيــس علــى‬\n      ‫فتــات مــن احلبــوب يــزن (‪ )0.2‬اثنــن مــن العشــرة مــن اجلــرام فتــم القبــض‬\n      ‫عليــه‪ .‬وعنــد حضــور املتهــم لالســتجواب تعــذر ذلــك كونــه كان يف‬\n      ‫حالــة ال ميكــن معهــا اســتجوابه ومت بعثــه ملستشــفى الصحــة النفســية‬\n      ‫لعالجــه وتزويدنــا بتقريــر عــن حالتــه‪ .‬وبتاريــخ ‪1433/8/19‬ه ـ مت إعــادة‬\n      ‫اســتجوابه واقــر بقيامــه بابتــاع الكيــس الــذي بــه احلبــوب واقــر بأنــه‬\n\n‫‪191‬‬\n\f‫يعــود لــه بقصــد التعاطــي كمــا اقــر بتعاطيــه الســابق للحبــوب‪ .‬وقــد‬\n‫اثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )........‬لعــام ‪1433‬ه ـ الصــادر‬\n‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية التابــع لــوزارة‬\n‫الصحــة مبنطقــة املدينــة املنــورة إيجابيــة العينــة لإلمفيتامــن احملظــور‬\n‫وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة واملنــوه عنهــا يف اجلــدول‬\n‫الثانــي فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫وانتهــى التحقيــق إلــى اتهــام املدعــى عليــه بحيــازة فتــات يــزن (‪)0.2‬‬\n‫اثنــن مــن العشــرة مــن اجلــرام مــن حبــوب اإلمفيتامــن احملظــورة بقصــد‬\n‫التعاطــي وتعاطيــه مــن الكميــة املضبوطــة معــه بابتالعهــا ولنوعهــا مــن‬\n‫الســابق واملجــرم علــى ذلــك وفقــا للمــادة الثالثــة الفقــرة الثانيــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م ‪ )39 /‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا‬\n‫جــاء بإقــراره املنــوه عنــه املــدون على الصفحة رقــم (‪ )4‬من دفتر التحقيق‬\n‫املرفــق برقــم (‪ -2 .)20‬مــا ورد مبحضــر القبــض املنــوه عنــه املرفــق لفــه‬\n‫رقــم (‪ -3.)1‬التقريــر الكيميائــي الشــرعي رقــم (‪ 1801‬ك م) املنــوه‬\n‫عنــه املرفــق لفــه (‪ -4.)27‬مــا ورد مبحضــر اثبــات واقعــة عنــد حضــوره‬\n‫لالســتجواب وهــو يف حالــة غيــر طبيعيــة املنــوه عنــه املــدون علــى الصفحة‬\n‫رقــم (‪ )3‬مــن دفتــر التحقيــق املرفــق برقــم (‪ .)20‬وبالبحــث عــن حالتــه‬\n‫اجلنائيــة عثــر لــه علــى ثــاث ســوابق حيــازة واســتعمال مخــدرات وقضيــة‬\n‫اشــتباه وشــرب املســكرات وســرقة مســاكن‪ .‬وحيــث أن مــا أقــدم عليــه‬\n‫املدعــى عليــه فعــل محــرم شــرعا ومعاقــب عليــه نظامــا مبوجــب نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة لــذا أطلــب إثبــات إدانتــه مبــا‬\n‫أســند إليــه واحلكــم عليــه باآلتــي‪ -1 :‬عقوبــة الســجن األصليــة اســتنادا‬\n\n\n                                                                                          ‫‪192‬‬\n\f      ‫للمــادة (‪ )41‬الفقــرة األولــى مــن النظــام املشــار إليــه‪ -2 .‬عقوبــة املنــع‬\n      ‫مــن الســفر خــارج اململكــة التكميليــة اســتنادا للمــادة (‪ )56‬الفقــرة‬\n      ‫(‪ )1‬مــن النظــام املشــار إليــه‪ -3 .‬تشــديد العقوبــة عليــه لقــاء تكــرار‬\n      ‫ســوابقه اســتنادا لتعميــم صاحــب الســمو امللكــي نائــب وزيــر الداخليــة‬\n      ‫رقــم (‪ )93958‬وتاريــخ ‪1429/8/23‬ه ـ هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه صحيــح كلــه‬\n      ‫وانــا نــادم عليــه هكــذا أجــاب وبعــد ســماع الدعــوى واالجابــة املتضمنــة‬\n      ‫مصادقــة املدعــى عليــه علــى دعــوى املدعــي العــام وبعــد االطــاع علــى‬\n      ‫اوراق وطيــات املعاملــة وملــا تقــدم فقــد ثبــت لــدي ادانــة املدعــى عليــه‬\n      ‫مبــا نســب إليــه شــرعا مــن حيازتــه فتــات يــزن (‪ )0.2‬اثنــن مــن العشــرة‬\n      ‫مــن اجلــرام مــن حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي وتعاطيــه‬\n      ‫لنوعهــا مــن الســابق وحكمــت بتعزيــره بســجنه مــدة ســتة أشــهر اعتبــارا‬\n      ‫مــن تاريــخ ايقافــه يف ‪1433/8/19‬ه ـ كمــا حكمــت مبنعــه مــن الســفر‬\n      ‫مــدة ســنتني تبــدأ مــن تاريــخ خروجــه مــن الســجن كمــا حكمــت بجلــده‬\n      ‫ســبعون جلــده لقــاء الســوابق املســجلة بحقــه وبذلــك قضيــت وبعــرض‬\n      ‫احلكــم علــى الطرفــن قــرر املدعــي العــام املعارضــة بــدون الئحــة‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم وعلــى ذلــك‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n      ‫وصحبــه وســلم حــرر يف ‪1433/8/19‬هــ‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم‬\n      ‫الثالثــاء املوافــق ‪1433/11/9‬ه ـ الســاعة التاســعة والنصــف افتتحــت‬\n      ‫اجللســة وقــد عــادت املعاملــة إلينــا مــن محكمــة االســتئناف مبكــة‬\n      ‫املكرمــة وبرفقهــا القــرار رقــم ‪ 33432672‬يف ‪1433/10/21‬ه ـ‬\n      ‫املتضمــن مــا نصــه ( وبدراســة احلكــم وصــورة ضبطــه قررنــا إعادتهــا‬\n\n\n‫‪193‬‬\n\f‫لفضيلــة حاكــم القضيــة ملالحظــة أن فضيلتــه لــم يحكــم علــى املدعــى‬\n‫عليــه لقــاء اســتعماله للحبــوب احملظــورة مــع اعترافــه بذلــك إلجــراء‬\n‫مــا يلــزم نحــو مــا أشــير اليــه واهلل املوفــق ) وعليــه أجيــب أصحــاب‬\n‫الفضيلــة قضــاة االســتئناف بــأن املدعــي العــام لــم يطالــب بدعــواه‬\n‫ايقــاع عقوبــة علــى املدعــى عليــه لقــاء تعاطيــه احلبــوب احملظــورة ولــم‬\n‫يــرد يف الئحــة دعــواه مــا يــدل علــى مطالبتــه بذلــك واحلكــم بإيقــاع‬\n‫عقوبــة علــى املدعــى عليــه لــم يطالــب بهــا املدعــي يف غيــر محلــه لــذا‬\n‫فليــس لــدي ســوى مــا حكمــت بــه علــى املدعــى عليــه ولــم يظهــر لــي‬\n‫خالفــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم حــرر يف ‪1433/11/9‬هــ‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم‬\n‫الثالثــاء املوافــق ‪1434/2/5‬ه ـ الســاعة العاشــرة افتتحــت اجللســة وفيهــا‬\n‫حضــر طــريف الدعــوى وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة وبرفقهــا قــرار املالحظــة رقــم ‪ 33476182‬وتاريــخ‬\n‫‪1433/12/22‬ه ـ مــن الدائــرة اجلزائيــة األولــى واملتضمــن مالحظــة‬\n‫أصحــاب الفضيلــة مــا نصــه( بدارســة احلكــم وصــورة ضبطــه قررنــا‬\n‫إعادتهــا لفضيلــة حاكــم القضيــة ملالحظــة أن مــا أجــاب بــه فضيلتــه‬\n‫غيــر مقنــع فقــد نصــت املــادة التاســعة واخلمســن بعــد املائــة مــن نظــام‬\n‫اإلجــراءات اجلزائيــة علــى أن احملكمــة ال تتقيــد بالوصــف الــوارد يف‬\n‫الئحــة الدعــوى وعليــه أن تعطــى الفعــل الوصــف الــذي يســتحقه ولــو‬\n‫كان مخالفـ ًا للوصــف الــوارد يف الئحــة الدعوى‪...‬الــخ ‪ ،‬فعلــى فضيلتــه‬\n‫إجــراء مــا يلــزم علــى نحــو مــا ذكــر يف قرارنــا الســابق) أ‪.‬ه ـ عليــه ونظر ُا‬\n‫لوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد حكمــت إضافــة علــى مــا‬\n‫ســبق بحــق املدعــى عليــه بتعزيــره بجلــده ســبعون جلــدة دفعــة واحــده لقــاء‬\n\n\n                                                                                        ‫‪194‬‬\n\f      ‫تعاطيــه احلبــوب احملظــورة التــي أقــر يف مجلــس احلكــم لــدي بتعاطيــه‬\n      ‫لنوعهــا وبذلــك قضيــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه القناعــة باحلكــم وبعرضــه علــى املدعــي العــام قــرر املعارضــة علــى‬\n      ‫احلكــم بــدون الئحــة حــرر يف ‪1434/2/5‬ه ـ وصلــى اهلل وســلم علــى‬\n                                                  ‫نبينــا محمــد والــه وصحبــة وســلم‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بقــرار احملكمــة ومضمونــه املصادقــة علــى احلكــم بعــد االجــراء‬\n      ‫االخيــر وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n‫‪195‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":190,"source_page_end":195,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"724ff835f7f1b903b87f17cd04d1678c77d434c02711e03e92bc0cb71faedc05","normalized_text_hash":"8aa8996f81af6117074ef76789b40ac5c3a598f0bd2f65347e2add3bc3fb98e9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p190-33416641"},{"id":"c1e60f98-7ece-5366-b56a-46b4b30185e6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر- إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن","document_number":"34203698","case_number":"33586086","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/18","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر- إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34203698 :‬تاريخه ‪33586086 :‬‬\n                  ‫رقم الدعوى‪33586086 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪ 34244108‬تاريخه ‪1434/06/18 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬حــد املســكر‪-‬‬\n‫إقــرار‪ -‬إدانــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬التعزيــر بالســجن‬\n                                                                ‫واإلبعــاد ‪.‬‬\n\n\n\n‫‪ -1‬القاعــدة الفقهيــة‪{ :‬املــرء مؤاخــذ بإقــراره}‪ ،‬والقاعــدة الفقهيــة‪:‬‬\n‫{إقــرار اإلنســان علــى نفســه مقبــول}‪ .‬املنثــور مــن القواعــد للزركشــي‬\n‫(‪ )188/1‬واألشــباه والنظائــر للســيوطي (‪ )465/1‬ودرر احلــكام (‪.)79/1‬‬\n‫‪ -2‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة‬\n‫(‪ )2‬مــن املــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة‬\n                                           ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n‫بقصــد التعاطــي وتعاطيــه لــه‪ ،‬واحلكــم عليــه بعقوبــة الســجن واإلبعــاد‬\n‫عــن البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n‫وحيــث إنــه مت تفتيــش املدعــى عليــه شــخصي ًا فوجــد يف جيبــه قطعــة‬\n‫مــن احلشــيش املخــدر وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n‫العينــة املرســلة للحشــيش املخــدر‪ ،‬كمــا أقــر أمــام احملكمــة مبــا‬\n\n                                                                                    ‫‪196‬‬\n\f      ‫أســنده إليــه املدعــي العــام‪ ،‬وحيــث إن املــرء مؤاخــذ بإقــراره وأن إقــرار‬\n      ‫اإلنســان علــى نفســه مقبــول‪ ،‬املدعــى عليــه أبــدى التوبــة وال يوجــد لــه‬\n      ‫ســوابق والكميــة احملــازة قليلــة‪ ،‬فقضــت احملكمــة بإدانــة املدعــى‬\n      ‫عليــه بجميــع مــا نســب إليــه وقــررت جلــده حــد املســكر ثمانــن جلــدة‬\n      ‫دفعــة واحــدة يف مــكان عــام وســجنه ملــدة شــهرين وإبعــاده عــن البــاد‬\n      ‫بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة‬\n                                                                      ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬املــازم القضائــي باحملكمــة‬\n      ‫اجلزائيــة باألحســاء يف املكتــب القضائــي الســادس وبنــاء علــى املعاملــة‬\n      ‫احملالــة مــن رئيــس احملكمــة اجلزائيــة باألحســاء برقــم (‪)33586086‬‬\n      ‫يف ‪1433/9/24‬ه ـ واملقيــدة برقــم (‪ )331749830‬يف ‪1433/9/24‬ه ـ‬\n      ‫وبنــاء علــى تعميــدي مــن فضيلــة الشــيخ‪ .......... /‬رئيــس احملكمــة‬\n      ‫اجلزائيــة باألحســاء املكلــف مبوجــب خطابــه رقــم (‪ )34970436‬يف‬\n      ‫‪1434/4/21‬ه ـ لنظــر القضايــا مــا عــدا الســجناء ويف يــوم األربعــاء‬\n      ‫املوافــق ‪1434/5/1‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة التاســعة‬\n      ‫يف هــذه القضيــة رقــم (‪ )3301700391‬وفيهــا حضــر املدعــي العام ‪........‬‬\n      ‫بالسجل املدني رقم (‪ )........‬وحضر حلضوره املدعى عليه ‪ ........‬مصري‬\n      ‫اجلنســية مبوجــب اإلقامــة الصــادرة مــن الريــاض برقــم (‪ )........‬وبســؤال‬\n      ‫املدعــي العــام عــن دعــواه قــال بصفتــي مدعيــا عامــا بدائرة االدعــاء العام‬\n      ‫مبحافظــة األحســاء أدعــي علــى ‪،........‬البالــغ مــن العمــر(‪ )33‬عام ـ ًا ‪،‬‬\n‫‪197‬‬\n\f‫‪ ........‬مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬محصــن‪،‬‬\n‫متعلــم ‪ ،‬موظــف أهلــي ‪ ،‬قبــض عليــه بتاريخ‪1433/8/21‬ه ـ واليــزال‬\n‫موقــوف مبوجــب امــر االيقــاف رقــم ( ‪ )........‬وتاريخ‪1433/8/22‬ه ـ‬\n‫ومت التمديــد لــه (‪ )25‬يوم ـ ًا ابتــداء مــن ‪1433/8/26‬ه ـ مبوجــب أمــر‬\n‫متديــد رقــم (ه ـ ق ‪ )43196/5/1‬وتاريــخ ‪1433/9/2‬هـ‪ ،‬اســتنادا لبرقية‬\n‫صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر‬\n‫الداخليــة رقــم ( ‪ ) 79425/4/5/1‬وتاريــخ ‪1432/12/20‬ه ـ وأحيــل‬\n‫للســجن العــام انــه بتاريــخ ‪1433/8/21‬ه ـ قبــض عليــه مــن قبــل إحــدى‬\n‫فــرق أمــن الطــرق مبحافظــة األحســاء اثــر اســتيقاف املدعــى عليــه‬\n‫وبرفقــة املدعــو (صــدر بحقــه امــر حفــظ ) وبقيادتــه ســيارة مــن نــوع‬\n‫(‪ )......‬حتمــل اللوحــة رقــم( ‪ ).....‬وبتفتيــش الســيارة بــدت عليــه عالمــات‬\n‫االرتبــاك الشــديد وعنــد تفتيشــهما وجــد يف جيــب املدعــى عليــه علــى‬\n‫قطعــة صغيــرة تــزن (‪/1‬جــم) جــرام يشــتبه انهــا مــن احلشــيش املخــدر‪،‬‬\n‫اثبــت التقريــر الكيميائي الشــرعي رقــم( ‪ )........‬لعام(‪1433‬هـ) ايجابية‬\n‫مــا مت ضبطــه معــه ملــادة احلشــيش املخــدر‪ .‬واملــدرج يف جــدول األول فئــه‬\n‫(أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبضبــط أقوالــه‪:‬‬\n‫أقــر بصحــة واقعــة القبــض و التفتيــش و بحيازتــه للحشــيش املخــدر‬\n‫لقصــد التعاطــي وتعاطيــه لنوعــه‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام لــه بحيــازة مــا وزنــه (‪)1‬جــرام مــن احلشــيش املخــدر لقصــد‬\n‫التعاطــي وتعاطيــه لنوعــه ‪،‬وذلــك لألدلــة والقرائــن التاليــة‪ 1 :‬ـ إقــراره‬\n‫املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )2-3‬مــن ملــف ســماع االقــوال‬\n‫ملرفــق علــى اللفــة رقــم(‪ 2 .)9‬ـ محضــر القبــض والتفتيــش املرفــق علــى‬\n‫اللفــة رقــم (‪ 3 )6‬ـ التقريــر الكيميائــي الشــرعي املرفــق علــى اللفــة‬\n\n\n                                                                                   ‫‪198‬‬\n\f      ‫رقــم (‪ .)24‬وبالبحــث عمــا إذا كان لــه ســوابق تبــن خلــو ســجله مــن‬\n      ‫الســوابق اجلنائيــة‪ .‬وحيــث أنــه مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n      ‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم و مجــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه مبــا يلــي‪.1 -:‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪) 41‬‬\n      ‫مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة لقــاء مــا اســند إليــه‬\n      ‫مــن اتهــام‪.2 .‬بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة ( ‪ ) 56‬مــن‬\n      ‫ذات النظــام وذلــك بإبعــاده خــارج البــاد‪ .‬هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام‬\n      ‫مــن قيامــي بحيــازة قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا جــرام (‪1‬جــم)‬\n      ‫لقصــد التعاطــي وتعاطــي لنوعــه فصحيــح وأنــا تائــب إلــى اهلل ونــادم‬\n      ‫علــى مــا بــدر منــي هكــذا أجــاب هــذا فتــم ســؤاله عــن عمــره فقــال‬\n      ‫أبلــغ مــن العمــر ‪ 35‬عامــا هكــذا قــال كمــا مت ســؤاله هــل أنــت متــزوج‬\n      ‫فقــال نعــم هكــذا قــال كمــا مت اطالعــي علــى التقريــر الكيميائــي‬\n      ‫الشــرعي املرفــق يف املعاملــة علــى اللفــة رقــم (‪ )24‬ويتضمــن (إيجابيــة‬\n      ‫قطعــة احلشــيش املخــدر املوصوفــة بالدعــوى) فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بدعــوى املدعــي العــام‬\n      ‫ولكــون هــذا اإلقــرار قــد صــدر مــن مكلــف (عاقــل بالــغ) وللقاعــدة‬\n      ‫الفقهيــة ((أن املــرء مؤاخــذ بإقــراره)) والقاعــدة ((إقــرار اإلنســان علــى‬\n      ‫نفســه مقبــول)) املنثــور مــن القواعــد للزركشــي [ج‪ ]188/1‬واألشــباه‬\n      ‫والنظائــر للســيوطي [ج‪ ]465/1‬ودرر احلــكام [ج‪ ]79/1‬وبعــد االطــاع‬\n\n\n‫‪199‬‬\n\f‫علــى تقريــر الكيميائــي الشــرعي لذلــك كلــه فقــد قــررت مــا يلــي‪:‬‬\n‫أوال‪ :‬ثبــت لــدي تعاطــي املدعــى عليــه للحشــيش املخــدر وقــررت جلــده‬\n‫حــد املســكر ثمانــن جلــدة حــدا دفعــة واحــدة يف مــكان عــام ثانيــا‪:‬‬\n‫ونظــرا لثبــوت حيــازة املدعــى عليــه للحشــيش املخــدر املوصــوف‬\n‫بالدعــوى بقصــد االســتعمال الشــخصي واملتوجــه تعزيــره حســبما نصــت‬\n‫عليــه الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫ونظــرا لكــون الكميــة املضبوطــة مــع املدعــى عليــه قليلــة ولكونــه‬\n‫أبــدى التوبــة والنــدم ولكونــه متــزوج وال يوجــد عليــه ســوابق وهــذه‬\n‫مســوغات معتبــرة يف تخفيــف العقوبــة عنــه وبنــاء علــى الفقــرة األولــى‬\n‫مــن املــادة (‪ )60‬مــن نفــس النظــام فقــد قــررت النــزول عــن أدنــى عقوبــة‬\n‫نــص عليهــا يف الفقــرة األولــى مــن املــادة (‪ )41‬وقــررت تعزيــر املدعــى‬\n‫عليــه بســجنه ملــدة شــهرين محســوبا منهــا مــدة توقيفــه ثالثــا‪ :‬ونظــرا‬\n‫لقيــام املدعــى عليــه بحيــازة احلشــيش املخــدر املوصــوف بالدعــوى‬\n‫وتعاطيــه لنوعــه وهــذه اجلرميتــان نصــت عليهــا الفقــرة الثانيــة مــن املــادة‬\n‫(‪ )3‬مــن نظــام مكافحــة املخــدرات وبنــاء علــى الفقــرة الثانيــة مــن املــادة‬\n‫(‪ )56‬مــن نفــس النظــام فقــد قــررت إبعــاد املدعــى عليــه عــن البــاد‬\n‫بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه‪ ،‬وال يســمح لــه بالعــودة فيمــا‬\n‫عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة ومبــا ســبق كلــه حكمــت‬\n‫وبعرضــه علــى املدعــى عليــه قــرر القناعــة بــه كمــا قــرر املدعــي العــام‬\n‫املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة‬\n‫اعتراضيــة وبذلــك تكــون القضيــة منتهيــة وقــررت بعــث كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم حســب املتبــع‬\n‫وبــاهلل التوفيــق واختتمــت اجللســة يف متــام الســاعة التاســعة والنصــف‬\n\n\n                                                                                      ‫‪200‬‬\n\f      ‫وللبيــان حــرر يف ‪1434/5/1‬ه ـ ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                   ‫وصحبــه وســلم تســليما كثيــرا‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافق‪1434/7/8‬ه ـ افتتحــت‬\n      ‫اجللســة يف هــذه الدعــوى املقدمــة مــن املدعــي العــام ضــد‪ ........‬يف قضيــة‬\n      ‫مخــدرات وبنــاء علــى رجــوع املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية مبوجــب خطابهــم رقــم (‪ )34/1249845‬يف ‪1434/6/25‬ه ـ‬\n      ‫وبرفقــه القــرار الصــادر مــن الدائــرة اجلزائيــة الثالثيــة األولــى ‪ -‬ج‪1/‬‬\n      ‫برقــم (‪ )34244108‬وتاريــخ ‪1434/6/18‬ه ـ ونــص احلاجــة منــه‬\n      ‫(وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن فضيلــة‬\n      ‫ناظــر القضيــة مــازم قضائــي والقضيــة بهــا ســجني فمــا وجــه مســتند‬\n      ‫فضيلتــه يف نظــر القضيــة واهلل املوفق)أ‪.‬ه ـ عليــه توقيــع وختــم أصحــاب‬\n      ‫الفضيلــة كل مــن قاضــي اســتئناف ‪ ، ........‬قاضــي اســتئناف ‪،........‬‬\n      ‫رئيــس الدائــرة ‪ ........‬بالنســبة للمالحظــة فمــا ذكــره أصحــاب الفضيلــة‬\n      ‫‪ -‬وفقهــم اهلل ‪ -‬مــن أن املــازم القضائــي ال ينظــر قضايــا الســجناء‬\n      ‫واملوقوفــن صحيــح وهــذا مــا نــص عليــه يف الفقــرة (و) مــن البنــد ثانيــا‬\n      ‫مــن املــادة الثامنــة مــن تنظيــم أعمــال املالزمــن القضائيــن ولكــن‬\n      ‫املدعــى عليــه لــم يكــن ســجينا قبــل نظرنــا للقضيــة بــل كان مفرجــا‬\n      ‫عنــه حيــث إنــه كان موقوفــا فأطلــق ســراحه كمــا هــو مبــن يف أوراق‬\n      ‫املعاملــة علــى اللفــة رقــم (‪ )47-42-41‬ثــم بعــد مضــي مــدة مــن اإلفــراج‬\n      ‫عــن املدعــى عليــه جــررت الكتابــة بعدهــا مــن فضيلــة الشــيخ‪........ /‬‬\n      ‫‪-‬ســلمه اهلل ‪ -‬لســعادة مديــر مكافحــة املخــدرات مبحافظــة األحســاء‬\n      ‫مبوجــب خطابــه رقــم (‪ )33/2077650‬يف ‪1434/1/28‬ه ـ إلبــاغ‬\n      ‫املدعــى عليــه مبوعــد جلســته ثــم ألفــى اجلــواب مبوجــب خطابهــم رقــم‬\n\n\n‫‪201‬‬\n\f‫(‪ )........‬يف ‪1434/4/29‬ه ـ املرفــق يف املعاملــة علــى اللفــة رقــم (‪)47‬‬\n‫ويتضمــن إبــاغ املدعــى عليــه مبوعــد جلســته وهــو يــوم األربعــاء املوافــق‬\n‫‪1434/5/1‬ه ـ فحضــر املدعــى عليــه يف املوعــد املذكــور آنف ـ ًا ولــم‬\n‫يكــن ســجينا‪ .‬فــإذا فــإن املدعــى عليــه لــم يكــن ســجينا كمــا ذكــر‬\n‫أصحــاب الفضيلــة ‪ -‬وفقهــم اهلل ‪ -‬وإمنــا مفــرج عنــه واملــادة املذكــورة‬\n‫بعاليــه إمنــا نصــت علــى أن املــازم القضائــي ممنــوع مــن نظــر دعــوى مــن‬\n‫كان ســجينا أو موقوفــا فعليــا وأحضــر إلــى مجلــس احلكــم ونظــرت‬\n‫دعــواه وهــو علــى تلــك الصفــة وهــذا ال يتحقــق يف املدعــى عليــه حيــث إنــه‬\n‫كان مفرجــا عنــه وال زال لــذا فلــم يظهــر لــي مــا يؤثــر علــى مــا حكمــت‬\n‫بــه واهلل ولــي التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                     ‫وســلم حرر‪1434/7/8‬هـ ــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي انــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n‫باالحســاء يف املكتــب الســادس ففــي يــوم األربعــاء املوافــق ‪1434/9/2‬‬\n‫افتتحــت اجللســة يف هــذه الدعــوى املقدمــة من املدعي العام ضــد‪.............‬‬\n‫يف قضيــة مخــدرات وبنــاء علــى رجــوع املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية مبوجــب خطابهــم رقــم (‪ )34/1928542‬يف‬\n‫‪1434/8/24‬ه ـ وبرفقــة القــرار الصــادر مــن الدائــرة اجلزائيــة الثالثيــة‬\n‫االولــى ج‪ 1/‬برقــم (‪ )34299191‬وتاريــخ ‪1434/8/16‬ه ـ ونصــه بعــد‬\n‫املقدمــة (وبدراســة القــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‬\n‫‪ 34244108‬يف ‪ 1434/6/18‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد‬\n‫اإليضــاح االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                      ‫وصحبــه وســلم حــرر ‪ 1434/9/2‬ه ـ )‪.‬‬\n\n\n\n                                                                                     ‫‪202‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":196,"source_page_end":202,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6926e6989252e4eb29fa955f77a37988a986721210cbf671f3226d1a96a72a96","normalized_text_hash":"ce34d441812e3496d0eedf83087e704791bfe03500c79e3dd8e11d00781ed138","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p196-34203698"},{"id":"27f4bf48-d66e-5d0c-bbb5-a7709b544faa","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -دخول التعزير يف احلد -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واإلبعاد .","document_number":"33467443","case_number":"33622809","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/24","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -دخول التعزير يف احلد -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33467443:‬تاريخه ‪1433/10/24:‬هـ‬\n                         ‫رقم الدعوى ‪33622809:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3419729‬تاريخه‪1434/01/21:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬حــد املســكر‬\n      ‫‪ -‬دخــول التعزيــر يف احلــد ‪ -‬إقــرار‪ -‬إدانــة‪ -‬نــزول عــن احلــد األدنــى‬\n                                     ‫للعقوبــة ‪ -‬التعزيــر بالســجن واإلبعــاد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول اهلل تعالــى‪ (( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر‪..‬‬\n                                                                                 ‫اآليــة))‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                                 ‫حــرام )‪.‬رواه مســلم‪.‬‬\n      ‫‪ -3‬جــاء يف الشــرح املمتــع (‪« :)293/14‬أن الصحابــة رضــي اهلل عنهــم ملــا‬\n                                                                      ‫تشــاوروا‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -4‬جــاء يف كشــاف القنــاع (‪« :)112/14‬أن علي ـ ًا أتــي بالنجاشــي قــد‬\n                                                                ‫شــرب خمــر ًا‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -5‬جــاء يف اإلنصــاف (‪« :)438/8‬وأبــو العبــاس يــرى أن حكمهــا حكــم‬\n                                                                     ‫الشــراب‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -6‬قــول شــيخ اإلســام رحمــه اهلل يف مجمــوع الفتــاوى (‪:)198/34‬‬\n      ‫«وكذلــك احلشيشــة املســكرة يجــب فيهــا احلــد‪ ..‬إلــخ»‪ .‬وقولــه‬\n                         ‫(‪« :)214/34‬الصحيــح أن احلشيشــة مســكرة‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -7‬جــاء يف فتــح البــاري (‪« :)45/10‬واســتدل مبطلــق قولــه صلــى اهلل‬\n               ‫عليــه وســلم‪( :‬كل مســكر حــرام) علــى حتــرمي مــا يســكر‪ ..‬إلــخ»‪.‬‬\n‫‪203‬‬\n\f‫‪ -8‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )2‬مــن املــادة (‪ )56‬والفقــرة (‪)1‬‬\n        ‫مــن املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫‪ -9‬قــرار هيئــة كبــار العلمــاء رقــم (‪ )53‬وتاريــخ ‪1397/4/4‬ه ـ الــذي‬\n‫تضمــن بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع كمــا‬\n                                                   ‫قــرر أنــه ثمانــون جلــدة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش‬\n‫املخــدر بقصــد التعاطــي وتعاطيــه لــه‪ ،‬حيــث إنــه مت تفتيــش الســيارة‬\n‫التــي يقودهــا املدعــى عليــه بعــد توفــر معلومــات عــن حيازتــه للحشــيش‬\n‫املخــدر فعثــر فيهــا علــى قطعــة مــن احلشــيش املخــدر‪ ،‬وأثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‪،‬‬\n‫كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬وحيــث‬\n‫إن احلشــيش مســكر وأنــه يقــام حــد املســكر علــى متعاطيــه‪ ،‬كمــا‬\n‫أنــه يجــوز اجلمــع بــن احلــد والتعزيــر فقضــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بجميــع مــا نســب إليــه وقــررت إقامــة حــد املســكر عليــه بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة يف مــكان عــام وســجنه ملــدة شــهرين ومنعــه‬\n‫مــن الســفر خــارج اململكــة مــدة ســنتني‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n‫وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                               ‫علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                    ‫‪204‬‬\n\f      ‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا القاضــي باحملكمــة اجلزائيــة بالدمــام ففــي يــوم الســبت املوافــق‬\n      ‫‪14 33/11/13‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن هيئــة التحقيــق واالدعــاء العــام برقــم ‪49936‬‬\n      ‫وتاريــخ ‪ 1433/10/22‬ه ـ واملقيــدة بــوارد مكتبنــا برقــم ‪33188838‬‬\n      ‫وتاريخ‪1433/10/24‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪........‬ضــد‬\n      ‫املدعــى عليــه ‪ ........‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪........‬‬\n      ‫وباالطــاع علــى محضــر واقعــة القبــض والضبــط والتفتيــش املعــد مــن‬\n      ‫رجــال مكافحــة املخــدرات بالدمــام تبــن أنــه يف يــوم الســبت املوافــق‬\n      ‫‪1433/9/23‬ه ـ توفــرت معلومــات عــن شــخص يدعــى ‪ ...........‬مــن احــد‬\n      ‫املصــادر انــه يحتــاز كميــة مــن احلشــيش املخــدر بحــي ‪........‬بالدمــام‬\n      ‫ومبراقبتــه شــوهدت ســيارة مــن نــوع ‪ .......‬يســتقلها شــخص ينطبــق عليــه‬\n      ‫الوصــف وبعــد وقوفــه عنــد إحــدى البقــاالت مت اســتيقافه وبتفتيشــه‬\n      ‫وتفتيــش ســيارته عثــر علــى قطعــة ذات لــون اســود تــزن جميعهــا (‪)9.9‬‬\n      ‫تســعة جرامات وتســعة من العشــرة من اجلرام يشــتبه أن تكون حشــيش‬\n      ‫مخــدر داخــل درج الســيارة وبالتأكــد مــن هويتــه اتضــح انــه وأثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬يف ‪1433/10/3‬ه ـ إيجابيــة‬\n      ‫العينــة مــن املــادة املضبوطــة للحشــيش املخــدر‪ .‬وقــد انتهــى التحقيــق إلــى‬\n      ‫اتهــام‪ /‬باالتي‪-1/‬حيازتــه قطعــة تــزن (‪ )9.9‬تســعة جرامــات وتســعة‬\n      ‫مــن العشــرة مــن احلشــيش املخــدر لقصــد التعاطــي ‪-2‬تعاطــي احلشــيش‬\n      ‫املخــدر وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬محضــر القبــض والضبــط‬\n\n‫‪205‬‬\n\f‫والتفتيــش املــدون علــى الصفحتــن رقــم ( ‪ )2‬و(‪)11‬مــن ملــف إجــراءات‬\n‫االســتدالل لفــة رقــم (‪ -2)1‬اعترافــه حتقيقــا مبــا اســند إليــه املــدون على‬\n‫الصفحــة رقــم (‪ ) 19-18‬مــن ملــف إجــراءات االســتدالل لفــة رقــم (‪-3)1‬‬\n‫التقريــر الكيمــاوي الشــرعي املرفــق علــى اللفــة رقــم (‪ .)14‬وحيــث إن‬\n‫مــا أقــدم عليــه املذكــور‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات مــا أســند إليــه وفقـ ًا‬\n‫للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واحلكــم‬\n‫عليــه مبــا يلي‪-1:‬بعقوبــة الســجن الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪)41‬‬\n‫مــن نظــام مكافحــة املخــدرات ‪-2‬إبعــاده عــن البــاد وفق ـ ًا للفقــرة (‪)2‬‬\n‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‪ .‬هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام أننــي قمــت‬\n‫بحيــازة قطعــة حشــيش بلــغ وزنهــا (‪ )9.9‬تســعة جرامــات وتســعة مــن‬\n‫العشــرة مــن احلشــيش بقصــد التعاطــي وأننــي أتعاطــى احلشــيش املخــدر‬\n‫كل ذلــك صحيــح هكــذا أجــاب وقــد جــرى اطالعــي علــى أوراق‬\n‫املعاملــة كمــا جــرى اطالعــي علــى التقريــر الكيمــاوي الشــرعي رقــم‬\n‫‪........‬وتاريــخ ‪1433/10/3‬ه ـ املرفــق باملعاملــة رقــم ( ‪ )15-14‬واملتضمــن‬\n‫ثبــوت إيجابيــة املضبــوط ملــادة احلشــيش املخــدر كمــا جــرى منــا االطالع‬\n‫علــى صحيفــة ســوابق املدعــى عليــه فوجــدت خاليــة فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ونظــرا ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه‬\n‫أعــاه وبعــد االطــاع علــى أوراق‪ .‬املعاملــة ودراســتها ونظــرا ملصادقــة‬\n‫املدعــى عليــه للتهمــة املنســوبة إليــه مــن قبــل املدعــي العــام‪ .‬ونظــرا إلــى‬\n‫أن مــا قــام بــه املدعــى عليــه هــو محــرم شــرعا ومجــرم نظامــا ونظــرا‬\n‫إلــى أن تعاطــي احلشــيش املخــدر يــؤدي إلــى اإلســكار‪ ،‬وقــد نــص أهــل‬\n\n\n                                                                                        ‫‪206‬‬\n\f      ‫العلــم علــى إقامــة احلــد علــى متنــاول احلشــيش كمــا ذكــر املــرداوي يف‬\n      ‫اإلنصــاف يف (‪ )438/8‬حيــث قــال‪« :‬وأبــو العبــاس يــرى أن حكمهــا‬\n      ‫حكــم الشــراب املســكر يف إيجــاب احلــد وهــو الصحيــح إن أســكرت‬\n      ‫أو كثيرهــا وإال حرمــت وعــزر فقــط» وقــال شــيخ اإلســام‪« :‬وكذلــك‬\n      ‫احلشيشــة املســكرة يجــب فيهــا احلــد ومــن ظــن أن احلشيشــة ال تســكر‬\n      ‫وإمنــا تغيــب العقــل بــا لــذة فلم يعــرف حقيقة أمرهــا» (‪ ،)198/34‬وقال‪:‬‬\n      ‫«الصحيــح أن احلشيشــة مســكرة كالشــراب» الفتــاوى (‪)214/34‬‬\n      ‫قــال ابــن حجــر‪« :‬واســتدل مبطلــق قولــه صلــى اهلل عليــه وســلم‪( :‬كل‬\n      ‫مســكر حــرام) علــى حتــرمي مــا يســكر ولــو لــم يكــن شــرابا فيدخــل‬\n      ‫يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي وغيــره بأنهــا مســكرة»‬\n      ‫فتــح البــاري (‪ )45/10‬واهلل تعالــى يقــول‪ ( :‬يــا أيهــا الذيــن آمنــوا إمنــا‬\n      ‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n      ‫لعلكــم تفلحــون ) ولقولــه صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر‬\n      ‫وكل خمــر حــرام )رواه مســلم «وألن الصحابــة ـ رضــي اهلل عنهــم ملــا‬\n      ‫تشــاوروا يف عهــد عمــر رضــي اهلل عنــه حــن أكثــر النــاس مــن شــربه‪،‬‬\n      ‫قــال عبــد الرحمــن بــن عــوف رضــي اهلل عنــه‪ :‬أخــف احلــدود ثمانــون‬\n      ‫فوافــق علــى ذلــك الصحابــة» أ‪.‬ه ـ الشــرح املمتــع (‪ )293/14‬واســتناد ًا‬\n      ‫لقــرار هيئــة كبــار العلمــاء رقــم ‪ 53‬وتاريــخ ‪1397/4/4‬ه ـ والــذي‬\n      ‫تضمــن بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع كمــا قــرر‬\n      ‫أنــه ثمانــون جلــدة ‪.‬أ‪.‬ه ـ وألنــه يســوغ اجلمــع بــن احلــد والتعزيــر إذا وجــد‬\n      ‫جنايتــن ملــا روى أحمــد بإســناده أن عليـ ًا أتــي بالنجاشــي قد شــرب خمر ًا‬\n      ‫يف رمضــان فجلــده ثمانــن احلــد وعشــرين ســوط ًا لفطــره يف رمضــان‬\n      ‫وأخرجــه أيضـ ًا عبدالــرزاق وابــن أبــي شــيبة والبيهقــي (كشــاف القنــاع‬\n\n\n‫‪207‬‬\n\f‫‪ )112/14‬وبنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ونظــرا خللــو ســجل املدعــى عليــه‬\n‫مــن الســوابق ونظــرا لقلــة الكميــة ونظــرا ملــا ظهر لي مــن أخالق املدعى‬\n‫عليــه ونظــرا إلــى أن مصيــر األجنبــي اإلبعــاد وبنــاء علــى الفقــرة رقــم (‪)1‬‬\n‫مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫والتــي تقتضــي النــزول عــن احلــد األدنــى مــن عقوبــة الســجن املنصــوص‬\n‫عليهــا يف املــادة (احلاديــة واألربعــن) ولــكل مــا ســبق‪( :‬أوالً)‪ :‬ثبــت لــدي‬\n‫إدانــة املدعــى عليــه مبــا نســب إليــه مــن حيازتــه قطعــة بلــغ وزنهــا تســعة‬\n‫جرامــات وتســعة مــن العشــرة مــن احلشــيش املخــدر بقصــد التعاطــي‬\n‫وبذلــك حكمــت وحكمــت علــى املدعــى عليــه لقــاء ذلــك مبــا يلــي‪)1( :‬‬\n‫حكمــت علــى املدعــى عليــه بســجنه شــهرين يحتســب منهــا مــا أمضــاه‬\n‫موقوفــا يف هــذه القضيــة وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n‫(‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ووفق ـ ًا للفقــرة‬\n‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪)2( .‬حكمــت علــى املدعــى عليــه بإبعــاده عــن اململكــة بعــد‬\n‫تنفيــذ العقوبــة احملكــوم بهــا عليــه وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n‫(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقلية‪(.‬ثانياً)‪:‬ثبــت‬\n‫لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن تعاطيــه للحشــيش املخــدر‬\n‫وبذلــك حكمــت للحــق العــام وحكمــت علــى املدعــى عليــه لقــاء ذلــك‬\n‫حــدا بجلــده ثمانــن جلــدة دفعــة واحــدة يف مــكان عــام إقامــة حلــد‬\n‫املســكر عليــه‪ .‬وبعــرض احلكــم علــى الطرفــن قنــع املدعــى عليــه أمــا‬\n‫املدعــي العــام فقــرر االعتــراض مكتفيــا مبــا يف أوراق املعاملــة وأغلقــت‬\n‫اجللســة الســاعة العاشــرة والربــع صباحــا وعلــى ذلــك جــرى التوقيــع‬\n\n\n                                                                                         ‫‪208‬‬\n\f      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1433/11/13‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n      ‫األربعــاء املوافــق ‪14 34/02/13‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n      ‫صباحــا وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية بخطــاب رئيــس محكمــة االســتئناف رقــم ‪34/109244‬‬\n      ‫وتاريــخ ‪1434/02/5‬ه ـ وبرفقهــا القــرار رقــم ‪ 3419729‬وتاريــخ‬\n      ‫‪1434/01/21‬ه ـ الصــادر مــن قضــاة الدائــرة اجلزائيــة الثانيــة وهــم‬\n      ‫فضيلــة الشــيخ‪ ......../‬وفضيلــة الشــيخ‪ ......../‬وفضيلــة الشــيخ‪......../‬‬\n      ‫واملتضمــن املصادقــة علــى احلكــم وللمعلوميــة فقــد جــرى حتريــره‬\n      ‫وختمــت يف الســاعة العاشــرة والنصــف صباح ـ ًا وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n                                                                ‫‪1434/02/13‬هــ‪.‬‬\n\n\n\n\n‫‪209‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":203,"source_page_end":209,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8f40d59d94513705ca90602e02b5682a7ef496abfbe7f93efcfcd501db992256","normalized_text_hash":"f24830cb2bdd8608d623a1b17995264e6b3cb914d63f737190f584d8777e027b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p203-33467443"},{"id":"f15967d5-f687-5ebb-a1ac-ec72826b6d67","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة هيروين بقصد التعاطي وتعاطيه -إقرار -إدانة- تشديد العقوبة -التعزير بالسجن واجللد واملنع من السفر .","document_number":"3413519","case_number":"33627341","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/17","year":"1434","subject":"مخدرات -حيازة هيروين بقصد التعاطي وتعاطيه -إقرار -إدانة- تشديد العقوبة -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3413519 :‬تاريخه‪1434/01/17 :‬هـ‬\n                   ‫رقم الدعوى‪33627341:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪34248054‬تاريخه‪1434/06/21:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة هيرويــن بقصــد التعاطــي وتعاطيــه‪ -‬إقــرار‪ -‬إدانــة‪-‬‬\n     ‫تشــديد العقوبــة ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n       ‫املواد (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة الهيرويــن بقصــد التعاطــي وتعاطيــه منــه ‪ ،‬واحلكــم عليــه‬\n‫بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة‪ .‬وحيــث إنــه قــد مت تفتيــش الســيارة التــي يقودهــا‬\n‫املدعــى عليــه واالشــتباه بهــا فعثــر فيهــا علــى الهيرويــن‪ ،‬وأقــر املدعــى‬\n‫عليــه أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام وأعلــن توبتــه‪،‬‬\n‫وملــا كان املدعــى عليــه مــن أربــاب الســوابق فقضــت احملكمــة بإدانــة‬\n‫املدعــى عليــه بجميــع مــا نســب إليــه وقــررت جلــده ثمانــن جلــدة دفعــة‬\n‫واحــدة حــد املســكر وســجنه ملــدة ســنة وشــهرين ومنعــه مــن الســفر‬\n‫خــارج اململكــة ملــدة ســنتني وجلــده مائــة جلــدة علــى دفعتــن لقــاء تعــدد‬\n‫ســوابقه وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‬\n                   ‫وقــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n                                                                                    ‫‪210‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 33627341‬وتاريــخ‬\n      ‫‪1433/10/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331906418‬وتاريــخ‬\n      ‫‪1433/10/28‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1433/12/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 :30‬وفيهــا حضــر املدعــي العــام املــدون خطــاب‬\n      ‫تعميــده يف قضايــا ســابقة وادعــى علــى احلاضــر معــه باملجلــس الشــرعي‬\n      ‫‪ ........‬ســعودي اجلنســية ســجل مدنــي رقــم ‪ ........‬قائــا يف دعــواه‬\n      ‫‪1433/10/11‬ه ـ مت القبــض علــى املدعــى عليــه قبــل إحــدى فــرق إدارة‬\n      ‫مكافحــة املخــدرات مبكــة املكرمــة لــورود معلومــات مــن أحــد‬\n      ‫مصادرهــم الســرية بــأن مجموعــة مــن األشــخاص يقومــون بتعاطــي‬\n      ‫الهيرويــن املخــدر بحــي ‪ ........‬وبانتقــال الفرقــة للحــي املشــار إليــه مت‬\n      ‫االشــتباه بســيارة كان يقودهــا املدعــى عليــه ويرافقــه شــخص آخــر‬\n      ‫(أطلــق ســراحه وحفــظ االتهــام بحقــه مــن قبــل جهــة التحقيــق لعــدم‬\n      ‫كفايــة االدلــة) وباســتيقافهما وتفتيشــهما ضبــط يف الســيارة مبقعــد‬\n      ‫املدعــى عليــه (بــن املقعــدة و ناقــل الســيارة ( القيــر )) كيــس بــه مــادة‬\n      ‫صفــراء اللــون بلــغ وزنهــا ( ‪2‬جــم ) جرامــن وقــد انتهــى التحقيــق معــه‬\n      ‫الــى اتهامــه بحيــازة كيــس بــه مــادة الهرويــن املخــدر بلــغ وزنــه ( ‪2‬جــم )‬\n      ‫جرامــن بقصــد التعاطــي وتعاطيــه للهيرويــن املخــدر يف الســابق وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -1 :‬إقــراره ‪ -2‬محضــري البــاغ والضبــط‬\n      ‫‪ -3‬التقريــر الكيميائــي الشــرعي لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n\n‫‪211‬‬\n\f‫إليــه واحلكــم عليــه مبــا يلــي‪1:‬ـ بالســجن وفقــا للمــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات‪ .2.‬منعــه مــن الســفر خلــارج البــاد بعــد انتهــاء تنفيذ‬\n‫عقوبتــه وفقــا للمــادة (‪ )56‬مــن نفــس النظــام‪3‬ـ التشــديد عليــه لكثــرة‬\n‫ســوابقه هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام صحيــح جملــة وتفصيــا وكانــت آخــر مــرة تعاطيــت فيهــا‬\n‫الهيرويــن قبــل أربــع ســنوات وأنــا تائــب إلــى اهلل عــز وجــل هــذا مــا لــدي‬\n‫وباالطــاع علــى املعاملــة وجــدت بــن طياتهــا علــى لفــة رقــم ‪ 28‬صحيفــة‬\n‫ســوابق املدعــى عليــه املتضمنــة وجــود ثــاث عشــرة ســابقة عليــه منهــا‬\n‫ثمــان حيــازة واســتعمال مخــدرات أو احداهمــا علــى مــا هــو مفصــل يف‬\n‫الصحيفــة فبنــاء علــى مــا ســبق مــن الدعــوى واالجابــة ومبــا أن االتهــام‬\n‫توجــه للمدعــى عليــه بحيــازة كيــس بــه مــادة الهيرويــن املخــدر بلــغ‬\n‫وزنــه جرامــن بقصــد التعاطــي وتعاطيــه لــذات النــوع يف الســابق ومبــا‬\n‫أن املدعــى عليــه أقــر مبــا اتهــم بــه ومبــا أن املدعــى عليــه ســوابق مــن‬\n‫جنــس هــذه القضيــة لذلــك فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة‬\n‫كيــس بــه مــادة الهيرويــن يــزن جرامــن بقصــد التعاطــي وتعاطيــه‬\n‫لــذات النــوع يف الســابق وحكمــت بجلــده ثمانــن جلــدة دفعــة واحــدة‬\n‫حــد املســكر لقــاء تعاطيــه للهيرويــن وســجنه ثمانيــة أشــهر حتتســب‬\n‫مــن تاريــخ إيقافــه لقــاء إدانتــه باحليــازة ولقــاء تعــدد ســوابقه ومنعــه مــن‬\n‫الســفر ملــدة ســنتني بعــد انتهــاء تنفيــذ عقوبتــه مــع التأكــد مــن عــدم‬\n‫تنفيــذ حــد املســكر علــى املدعــى عليــه خــال الســنوات األربــع املاضيــة‬\n‫وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي‬\n‫العــام االعتــراض بالئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/12/29‬ه ـ احلمــد‬\n\n\n                                                                                        ‫‪212‬‬\n\f      ‫هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق‪ 1434/05/13‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وقــاد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫برقــم ‪ 331906418‬يف ‪1434/4/24‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة‬\n      ‫اخلامســة رقــم ‪ 34193445‬يف ‪1434/4/21‬ه ـ متضمنــا بعــد املقدمــة‬\n      ‫مــا نصــه وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n      ‫إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن العقوبــة قليلــة جــدا لكثــرة‬\n      ‫ســوابقه فالبــد مــن عقوبــة زاجــرة رادعــة واهلل املوفــق عليــه أشــكر‬\n      ‫أصحــاب الفضيلــة ولوجاهــة مــا ذكــروه فقــد حكمــت إضافــة إلــى‬\n      ‫مــا ســبق بســجنه أربعــة أشــهر إضافيــة وجلــده مائــة جلــدة مفرقــة علــى‬\n      ‫دفعتــن متســاويتني بينهمــا أســبوع لقــاء تعــدد ســوابقه وبعرضــه علــى‬\n      ‫الطرفــن قــرر املدعــي العــام بقــاءه علــى االعتــراض وقــرر املدعــى‬\n      ‫عليــه القناعــة وبــه ختمــت اجللســة الســاعة احلاديــة عشــر والربــع وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                           ‫يف ‪ 1434/05/13‬ه ـ ‪.‬‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جرى منا نحن قضاة الدائرة اجلزائية اخلامســة مبحكمة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n      ‫احملكمة مبكة املكرمة برقم ‪ 341079292‬وتاريخ ‪ 1434/6/11‬هـ‬\n      ‫املرفــق بهــا القــرار رقــم ‪ 3413519‬وتاريــخ ‪ 1434/1/17‬ه ـ الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ......... /‬القاضــي باحلكمــة اجلزائيــة مبكــة املكرمــة‬\n      ‫املتضمــن دعــوى املدعــي العــام ضــد ‪ ....... /‬ســعودي اجلنســية املتهــم يف‬\n      ‫مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n\n‫‪213‬‬\n\f‫ضبطــه قررنــا املوافقــة علــى احلكــم بعــد االجــراء االخيــر ‪ ،‬واهلل املوفــق‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪214‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":210,"source_page_end":214,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"69245ffe9fc208a7f7cdd02a429252bb623e5428418e919aff3bc6c9fa24d883","normalized_text_hash":"03890e7c7b22420ddad56f3fcff18a4d5fdc38d919401687d67ed4256c99ea57","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p210-3413519"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"dbfe6176-edb7-510a-9f28-fd78b7feb15e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر - إقرار -إدانة -التعزير بالسجن .","document_number":"33394061","case_number":"33543638","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف أنه لم يتم تطبيق املواد املنظمة إليداع املدمن يف مصحة للعاج قبل احلكم بذلك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/08/24","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر - إقرار -إدانة -التعزير بالسجن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33394061:‬تاريخه‪1433/08/24:‬هـ‬\n                         ‫رقم الدعوى‪33543638:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪3441617‬تاريخه‪1434/02/19:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه ‪ -‬حــد املســكر ‪-‬‬\n                                            ‫إقــرار‪ -‬إدانــة ‪ -‬التعزيــر بالســجن ‪.‬‬\n\n\n\n\n                                                     ‫‪ -1‬اإلقرار حجة على املقر‪.‬‬\n                                                              ‫‪ -2‬ال عذر ملن أقر‪.‬‬\n      ‫‪ -3‬املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬واملــادة (‪ )43‬مــن نظــام‬\n                                     ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n      ‫‪ -4‬الفقــرة (أ) مــن الفقــرة (‪ )2‬والفقــرات (‪ )6،7‬مــن املــادة الثانيــة‬\n      ‫والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات واملؤثرات‬\n                                                                        ‫العقليــة‪.‬‬\n      ‫‪ -5‬توجيه وكيل الوزارة للشؤون القضائية ذي الرقم ‪.27/36420/28‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي وتعاطيــه لــه ‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع‬\n      ‫مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n      ‫حيــث إنــه مت تفتيــش الســيارة التــي يقودهــا املدعــى عليــه فعثــر فيــه علــى‬\n      ‫ســيجارة مــن احلشــيش املخــدر‪ ،‬وأثبــت التقريــر الكيمــاوي الشــرعي‬\n\n‫‪177‬‬\n\f‫احتــواء العينــة املرســلة علــى احلشــيش املخــدر وأقــر املدعــى عليــه أمــام‬\n‫احملكمــة مبــا أســنده إليــه املدعــي العــام وأعلــن ندمــه وطلــب عالجــه‬\n‫مــن اإلدمــان‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بجميــع مــا نســب إليــه وقــررت جلــده ثمانــن جلــدة دفعــة واحــدة‬\n‫حــد املســكر علنـاً‪ ،‬كمــا أمــرت بإيداعــه ملــدة ســتة أشــهر يف مصحــة‬\n‫مخصصــة لعــاج املدمنــن وأفهمتــه مبنعــه مــن الســفر خــارج اململكــة‬\n‫ملــدة ســنتني‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪،‬‬\n‫والحظــت محكمــة االســتئناف أنــه لــم يتــم تطبيــق املــواد املنظمــة إليــداع‬\n‫املدمــن يف مصحــة للعــاج قبــل احلكــم بذلــك‪ ،‬ورجعــت احملكمــة عمــا‬\n‫حكمــت بــه يف الفقــرة (الثانيــة) وقــررت أخيــر ًا ســجن املدعــى عليــه‬\n‫ســتة أشــهر‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪،‬‬\n                    ‫وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا القاضــي باحملكمــة اجلزئيــة بالقطيــف‬\n‫بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم ‪ ........‬يف‬\n‫‪1433/8/24‬ه ـ والــواردة بكتــاب رئيــس دائــرة التحقيــق واالدعــاء‬\n‫العــام مبحافظــة القطيــف بكتابــه ذي الرقــم ه ـ ق‪ 2374/2/4‬يف‬\n‫‪1433/8/21‬ه ـ حضــر املدعــي العــام مبوجــب كتــاب التكليــف رقــم‬\n‫‪ ........‬يف ‪1431/9/15‬ه ـ وادعــى علــى احلاضــر معــه ‪ ........‬بالســجل‬\n‫ا يف دعــواه إنــه بتاريــخ ‪1433/7/10‬ه ـ مت‬       ‫املدنــي رقــم ‪ ........‬قائ ـ ً‬\n‫القبــض علــى املدعــى عليــه أثنــاء قيــام الدوريــات األمنيــة بالدمــام‬\n‫بواجبهــا عنــد نقطــة التفتيــش بعــد اســتيقاف مركبتــه وبتفتيشــها‬\n\n                                                                                    ‫‪178‬‬\n\f      ‫عثــر علــى ســيجارة بلــغ وزنهــا (‪ )1.2‬جــرام واحــد واثنــان مــن العشــرة‬\n      ‫مــن اجلــرام بــن املرتبتــن أثبــت التقريــر الكيمــاوي الشــرعي الصــادر‬\n      ‫مــن املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية رقــم (‪)........‬‬\n      ‫‪1433/7/14‬ه ـ احتوائهــا ملــادة احلشــيش املخــدرة واحملظــورة وقــد انتهى‬\n      ‫التحقيــق معــه إلــى توجيــه االتهــام إليــه بحيــازة ســيجارة بلــغ وزنهــا (‪)1.2‬‬\n      ‫جــرام واحــد واثنــان مــن العشــرة مــن اجلــرام بقصــد التعاطــي وتعاطيــه‬\n      ‫لنوعهــا وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى ثــاث ســوابق‬\n      ‫ســابقتي حيــازة واســتعمال مخــدرات وســابقة ســرقة وحيــث أن مــا أقــدم‬\n      ‫عليــه املذكــور ‪-‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا اطلــب إثبــات مــا اســند إليــه وفق ـ ًا‬\n      ‫للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪-1 :‬بعقوبــة الســجن الــواردة‬\n      ‫بالفقــرة (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام املشــار إليــه ‪-2‬منعــه مــن‬\n      ‫الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم(‪ )56‬مــن النظــام املشــار إليــه‬\n      ‫ال‬‫هــذا مــا ادعــى بــه وبعرضــه علــى املدعــى عليــه وبســؤاله عنه أجــاب قائ ً‬\n      ‫مــا ذكــره املدعــي العــام يف دعــواه ضــدي مــن اتهامــي بحيــازة مــا ذكــر‬\n      ‫لغــرض التعاطــي وقيامــي بتعاطــي احلشــيش املخــدر كلــه صحيــح وأنــا‬\n      ‫نــادم علــى مــا اقترفــت وأطلــب عالجــي مــن ممــا ابتليــت بــه وقــد ذهبــت‬\n      ‫لغــرض العــاج إال أنــه مت االعتــذار مــن اســتقبال حالتــي لوجــود حــاالت‬\n      ‫مقدمــة هــذا مــا أجــاب بــه وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n      ‫الشــرعي رقــم (‪ )........‬وتاريــخ ‪1433/7/14‬ه ـ املرفــق باملعاملــة باللفــة‬\n      ‫رقــم (‪ )14‬وتبــن مطابقتــه ملــا عطــف عليــه املدعــي العــام فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه مبــا نســبه لــه املدعــي‬\n\n\n‫‪179‬‬\n\f‫العــام وألن اإلقــرار حجــة علــى املقــر وال عــذر ملــن أقــر وبنــاء علــى املــادة‬\n‫احلاديــة واألربعــن والسادســة واخلمســن مــن نظــام مكافحــة املخــدرات‬\n‫ولضآلــة الكميــة التــي حازهــا املدعــى عليــه وإلظهــاره للتوبــة والنــدم‬\n‫ولرغبتــه يف العــاج ولوجــود ســابقتني قريبتــن مــن جنــس القضيــة‬\n‫الالحقــة إذ مت احلكــم يف آخرهمــا بتاريــخ ‪1432/6/5‬ه ـ واحلكــم يف‬\n‫التــي قبلهــا بتاريــخ ‪1433/2/6‬ه ـ ممــا يفيــد عــدم ارتــداع املدعــى عليــه‬\n‫مبــا مت احلكــم عليــه بــه ممــا يتجــه معــه التشــديد يف العقوبــة وعــدم‬\n‫انتفاعــه باملــادة الســتني مــن نظــام مكافحــة املخــدرات وبنــاء علــى‬\n‫املــادة الثالثــة واألربعــن منــه وبنــاء علــى الفقــرة (أ) مــن الفقــرة الثانيــة‬\n‫مــن املــادة الثانيــة والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة‬\n‫املخــدرات وبنــاء علــى توجيــه وكيــل الــوزارة للشــؤون القضائيــة ذي‬\n‫الرقــم ‪ 27/36420/28‬والــذي يتضمــن أنــه ينبغــي للقاضــي بعــد تقريــر‬\n‫العقوبــة األصليــة إفهــام احملكــوم عليــه مبقتضاهــا وينــص علــى ذلــك‬\n‫يف الضبــط والقــرار لــذا وجلميــع مــا تقــدم فقــد ثبــت لــدي حيــازة املدعــى‬\n‫عليــه للكميــة املوصوفــة يف الدعــوى وقيامــه بتعاطــي احلشــيش املخــدر‬\n‫وقــررت أو ًال جلــد املدعــى عليــه ثمانــن جلــدة دفعــة واحــدة حــد املســكر‬\n‫علن ـ ًا ثاني ـ ًا األمــر بإيــداع املدعــى عليــه مــدة ســتة أشــهر يحتســب منهــا‬\n‫مــدة إيقافــه بســبب هــذه القضيــة يف مصحــة مخصصــة لعــاج املدمنــن‬\n‫يعالــج خاللهــا مــن إدمانــه بنــاء علــى الفقــرة السادســة والســابعة من املادة‬\n‫الثانيــة والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات‬\n‫بعــد التحقــق مــن إدمانــه بتقريــر طبــي يصــدر مــن مصحــة مخصصــة‬\n‫لهــذا الغــرض بنــاء علــى الفقــرة األولــى مــن املــادة الثانيــة والثالثــن مــن‬\n‫الالئحــة التنفيذيــة لنظــام مكافحــة املخــدرات فــإن بــان عــدم إدمانــه‬\n\n\n                                                                                          ‫‪180‬‬\n\f      ‫فيوقــع علــى املدعــى عليــه عقوبــة الســجن بــذات املــدة املقــررة لإليــداع‬\n      ‫يف املصحــة محتســب منهــا مــدة إيقافــه بســبب هــذه القضيــة ومبــا‬\n      ‫ذكــر حكمــت وأفهمــت املدعــى عليــه مبضمــون الفقــرة األولــى مــن‬\n      ‫املــادة السادســة واخلمســن مــن نظــام مكافحــة املخــدرات مبنعــه مــن‬\n      ‫الســفر مــدة ســنتني تبــدأ بعــد إنهــاء محكوميتــه وأن لوزيــر الداخليــة‬\n      ‫اإلذن بالســفر أثنــاء مــدة املنــع للضــرورة ففهــم ذلــك وبعــرض احلكــم‬\n      ‫علــى الطرفــن اعتــرض عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي‬\n      ‫الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه وســيتم بعــث املعاملــة حملكمــة‬\n      ‫االســتئناف بالدمــام لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف‬\n      ‫‪1433/8/26‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                             ‫أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية بكتــاب فضيلــة رئيســها رقــم ‪331656221‬‬\n      ‫يف ‪1433/11/24‬ه ـ املقيــدة يف هــذه احملكمــة برقــم ‪ ........‬يف‬\n      ‫‪1433/11/28‬ه ـ واحملالــة مــن فضيلــة الرئيــس وبرفقهــا القــرار الصادر‬\n      ‫مــن أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى رقــم ‪ ........‬يف‬\n      ‫‪1433/11/15‬ه ـ ونصــه بعــد املقدمــة وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة لوحــظ أن فضيلــة ناظــر القضيــة حكــم بإيــداع املدعــى‬\n      ‫عليــه باملصحــة ولــم يطبــق مقتضــى الفقــرة األولــى مــن املــادة الثانيــة‬\n      ‫والثالثــن ومــا بعدهــا ومــا قــرره فضيلتــه ســابق ألوانــه ملالحظــة مــا‬\n      ‫ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1433/11/14‬ه ـ قاضي‬\n      ‫اســتئناف ‪ ........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه‬\n\n\n‫‪181‬‬\n\f‫رئيــس الدائــرة ختمــه وتوقيعــه أ‪.‬ه ـ وأجيــب أصحــاب الفضيلــة وفقنــي‬\n‫اهلل وإياهــم إلصابــة الصــواب بأنــه جــرى األمــر بتطبيــق الفقــرة األولــى‬\n‫مــن املــادة الثانيــة والثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة‬\n‫املخــدرات كمــا هــو ظاهــر مــن الفقــرة الثانيــة مــن منطــوق احلكــم‬\n‫هــذا مــا لــزم جوابـ ًا علــى مالحظــة أصحــاب الفضيلــة ولفضيلتهــم فائــق‬\n‫التقديــر واالحتــرام وللبيــان حــرر يف ‪1434/1/6‬ه ـ وصلــى اهلل وســلم‬\n                          ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية بكتــاب فضيلــة رئيســها رقــم يف ‪1434/2/26‬ه ـ‬\n‫املقيــدة يف هــذه احملكمــة برقــم ‪ 34532790‬يف ‪1434/3/1‬ه ـ واحملالــة‬\n‫مــن فضيلــة الرئيــس وبرفقهــا القــرار الصــادر مــن أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة اجلزائيــة األولى رقم ‪ 3441617‬يف ‪1434/2/19‬هـ ونصه‬\n‫بعــد املقدمــة حيــث ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع علــى‬\n‫مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء علــى‬\n‫قرارنــا رقــم ‪/33455414‬ج‪/1‬ب يف ‪1433/11/15‬ه ـ لوحــظ أن تطبيــق‬\n‫املــادة املشــار إليهــا يكــون بعــد التحقيــق مــن إدمــان املدعــى عليــه بتقرير‬\n‫طبــي وهــذا لــم يكمــل الزمــه فضيلتــه ملالحظــة مــا ذكــر وإكمــال‬\n‫الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمد‬\n‫وآلــه وصحبــه وســلم حــرر يف ‪1434/2/17‬ه ـ قاضــي اســتئناف ‪........‬‬\n‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫‪ ........‬ختمــه وتوقيعــه أ‪.‬ه ـ عليــه فقــد حضــر املدعــي العــام واملدعــى‬\n‫عليــه وبســؤال املدعــى عليــه عــن كيفيــة القبــض عليــه وهــل كان بنــاء‬\n‫ا لقــد ألقــي القبــض علــي يف‬  ‫علــى بــاغ أو شــكوى ضــده أجــاب قائ ـ ً‬\n\n\n                                                                                       ‫‪182‬‬\n\f      ‫نقطــة التفتيــش ولــم يســبقه شــكوى أو بــاغ ضــدي هــذا مــا أجــاب بــه‬\n      ‫وبالرجــوع إلــى الئحــة نظــام املخــدرات وتأملهــا بنــاء علــى الفقــرة (ج) مــن‬\n      ‫الفقــرة الثانيــة مــن املــادة الثانيــة والثالثــن مــن الئحــة نظــام مكافحــة‬\n      ‫املخــدرات والتــي تتضمــن أن املدمــن مــن تضبطــه اجلهــات املختصــة بنــاء‬\n      ‫علــى شــكوى أو بــاغ لــذا وملــا تقــدم فقــد رجعــت عــن الفقــرة الثانيــة‬\n      ‫مــن منطــوق احلكــم وقــررت ســجن املدعــى عليــه ســتة أشــهر يحتســب‬\n      ‫منهــا مــدة إيقافــه بســبب هــذه القضيــة وبــه حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن اعتــرض عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي‬\n      ‫الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه وســيتم بعــث كامــل املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف‬\n      ‫‪1434/5/1‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                ‫أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالدمــام بكتــاب فضيلــة رئيســها رقــم ‪ 341171418‬يف ‪1434/6/20‬هـ‬\n      ‫املقيــدة يف هــذه احملكمــة برقــم ‪ 341171418‬يف ‪1434/6/24‬ه ـ‬\n      ‫واحملالــة مــن فضيلــة الرئيــس وبرفقهــا إعــام احلكــم الصــادر مني برقم‬\n      ‫‪ 33394061‬يف ‪1433/8/26‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلة قضاة‬\n      ‫الدائــرة اجلزائيــة األولــى رقــم ‪ 34238210‬يف ‪1434/6/12‬ه ـ ونصــه‬\n      ‫بعــد املقدمــة حيــث ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم ‪ 3441617‬يف ‪1434/2/19‬ه ـ قررنــا املصادقــة علــى‬\n      ‫احلكــم بعــد االجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/6/11‬ه ـ قاضــي اســتئناف ‪........‬‬\n\n\n‫‪183‬‬\n\f‫ختمــه وتوقيعــه قاضــي اســتئناف ‪ ........‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫‪ ........‬ختمــه وتوقيعــه أ‪.‬ه ـ وللبيــان حــرر يف ‪1434/6/24‬ه ـ وصلــى اهلل‬\n                  ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n                                                                               ‫‪184‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":177,"source_page_end":184,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"860d300133cf510b41034034a1def271995c10d223e876d2b7f3c8b2cd66e00f","normalized_text_hash":"80f587442b18167b074fe16e6a6b65bf4eb387760550c6a41f44137205f979d0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p177-33394061"},{"id":"b9d36ad3-07e6-5030-84fc-012e18687977","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي -قات -ضآلة الكمية املضبوطة -التعزير بالسجن و اإلبعاد عن الباد .","document_number":"3441034","case_number":"33574679","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/19","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي -قات -ضآلة الكمية املضبوطة -التعزير بالسجن و اإلبعاد عن الباد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪3441034:‬ىتاريخه‪1434/2/19:‬هـ‬\n                        ‫رقم الدعوى‪33574679:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3460557‬تاريخه‪1434/03/11:‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي ‪ -‬قــات ‪ -‬ضآلــة الكميــة املضبوطــة‬\n                                   ‫‪ -‬التعزيــر بالســجن و اإلبعــاد عــن البــاد ‪.‬‬\n\n\n\n\n                              ‫‪ -1‬املادة ‪ 159‬من نظام اإلجراءات اجلزائية ‪.‬‬\n      ‫‪-2‬الفقــرة األولــى مــن األمــر الســامي الكــرمي رقــم (‪ )59633‬يف‬\n                                                       ‫‪1432 /12 /9‬هــ‪.‬‬\n      ‫‪ -3‬املادة الرابعة من قرار وزير الداخلية رقم ( ‪ ) 2057‬يف ‪1404/5/26‬هـ‪.‬‬\n                    ‫‪ -4‬قرار وزير الداخلية رقم (‪ )3818‬يف ‪1410/9/28‬هـ ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة قــات بقصــد االســتعمال‬\n      ‫الشــخصي وتســتره علــى مصــدر مــا مت ضبطــه و طلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم بتعزيــره وفــق املــادة الرابعــة مــن قــرار مجلــس الــوزراء‬\n      ‫رقــم(‪ )11‬لعــام ‪1374‬ه وتشــديد العقوبــة لقــاء تســتره و حيــث مت القبــض‬\n      ‫علــى املدعــى عليــه مــن قبــل فرقــة مكافحــة املخــدرات وبتفتيشــه عثــر‬\n      ‫بحوزتــه كميــة مــن نبــات القــات وأثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور وصــادق املدعــى عليــه‬\n      ‫علــى االدعــاء املوجــه إليــه بحيــازة القــات بقصــد االســتعمال الشــخصي‪،‬‬\n\n‫‪185‬‬\n\f‫ونظــر ًا لعــدم وجــود ســوابق عليــه ولضآلــة مــا ضبــط بحوزتــه حكمــت‬\n‫احملكمــة بتعزيــره بالســجن مــدة شــهر ونصــف وإبعــاده إلــى بــاده بعــد‬\n‫انتهــاء محكوميتــه وصــرف النظــر عــن طلــب املدعــي العــام تشــديد‬\n‫العقوبــة علــى املدعــى عليــه لقــاء اتهامــه بالتســتر ألن ذلــك مندفــع مبــا‬\n‫علــم مــن بائعــي القــات مــن تخفيهــم وتنكرهــم وقنــع املدعــى عليــه‬\n‫باحلكــم واعتــرض املدعــي العــام بــدون الئحــة و صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بجــازان وبنــاء علــى املعاملــة الــواردة مــن دائــرة االدعــاء العــام بجــازان‬\n‫واملقيــدة بــوارد احملكمــة برقــم (‪ )331703298‬وتاريــخ ‪1433/9/13‬هـ‬\n‫واحملالة من فضيلة الرئيس برقم (‪ )33574679‬وتاريخ ‪1433/9/13‬هـ‬\n‫واملتعلقــة بدعــوى املدعــي العــام ضــد ‪.....‬املتهــم يف قضيــة قــات وقــد‬\n‫أعيــدت لعرضهــا علــى اللجنــة املكلفــة بتطبيــق تعليمــات العفــو بخطابنا‬\n‫رقــم (‪ )331703298‬وتاريــخ ‪1433/9/18‬ه ـ وأعيــدت متضمنــة عــرض‬\n‫املدعــى عليــه علــى اللجنــة املذكــورة وتقريرهــا عــدم شــموله بالعفــو‬\n‫كمــا دون علــى اللفتــن (‪ )34،33‬عليــه ففــي هــذا اليــوم األحــد‬\n‫‪1434/2/17‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة الثانيــة عشــرة‬\n‫اال ربعــا وفيهــا حضــر املدعــي العــام ‪.....‬املوجــه باخلطــاب رقــم (‪).....‬‬\n‫وتاريــخ ‪1433/3/22‬ه ـ وادعــى علــى احلاضر‪.....‬مينــي اجلنســية يحمــل‬\n‫البطاقــة البديلــة رقــم (‪ ).....‬يف ‪1433/8/19‬ه ـ الصــادرة مــن اإلدارة‬\n‫العامــة ملكافحــة املخــدرات أنــه بتاريــخ ‪1433/8/19‬ه ـ وأثنــاء قيــام‬\n\n                                                                                      ‫‪186‬‬\n\f      ‫أفــراد مكافحــة املخــدرات بواجبهــم امليدانــي يف قريــة ‪.....‬مت القبــض‬\n      ‫علــى املدعــى عليــه وبتفتيشــه عثــر معــه علــى كميــة مــن نبــات القــات‬\n      ‫احملظــور بلــغ وزنهــا (‪149‬ج ــم) مائــة وتســعة وأربعــن جرامــا واملثبتــة‬\n      ‫بالتقريــر الكيميائــي الشــرعي رقــم (‪.....‬للعــام ‪1433‬هــ) الصــادر‬\n      ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بجــازان‬\n      ‫(وبرفقتــه ‪.....‬أفــرج عنــه ولــم يوجــه لــه االتهــام وأحيــل جلهــة االختصــاص‬\n      ‫لكونــه مقيمــا بطريقــه غيــر مشــروعه) ومبواجهــة املدعــى عليــه بالتهمة‬\n      ‫املنســوبة وبأقوالــه مبحضــر ســماع األقــوال أقــر بصحــة واقعــة القبــض‬\n      ‫وأن الكميــة املضبوطــة مــن نبــات القــات احملظــور عائــدة لــه وغرضــه‬\n      ‫منهــا االســتعمال الشــخصي وأنــه حصــل عليهــا بالشــراء مــن شــخص‬\n      ‫ال يعرفــه وصــادق علــى أقوالــه حتقيقــا وبالبحــث عــن ســوابقه لــم يعثــر‬\n      ‫لــه علــى ســوابق مســجلة حتــى تاريخــه وقــد أســفر التحقيــق معــه عــن‬\n      ‫توجيــه االتهــام إليــه بحيــازة الكميــة املضبوطــة مــن نبــات القــات بقصــد‬\n      ‫االســتعمال الشــخصي وتســتره على مصدر ما مت ضبطه وطلب املدعي‬\n      ‫العــام إثبــات إدانتــه مبــا أســند إليــه واحلكــم بتعزيــره اســتناد ًا إلــى املــادة‬\n      ‫الرابعــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ وتشــديد‬\n      ‫العقوبــة عليــه لقــاء تســتره علــى مصــدر مــا مت ضبطــه وبعــرض دعــوى‬\n      ‫املدعــي العــام علــى املدعــى عليــه صــدق مــا جــاء فيهــا جملــة وتفصيــا‬\n      ‫وقــرر أنــه حصــل علــى كميــة القــات املضبوطــة مــن شــخص مينــي ال‬\n      ‫يعرفــه بقريــة ‪.....‬مقابــل خمســن ريــا ًال هكــذا أجــاب وبالرجــوع إلــى‬\n      ‫أوراق املع ــاملة جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي وثبــت‬\n      ‫ســوابق املدعــى عليــه فوجــدت مطابقــة ملــا يف الدعــوى عليــه فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وملــا تضمنــه األمــر الســامي الكــرمي رقــم‬\n\n\n‫‪187‬‬\n\f‫(‪ )59633‬وتاريــخ ‪1432/12/9‬ه ـ يف فقرتــه األولــى مــن املوافقــة على أن‬\n‫تطبــق احملاكــم علــى مرتكبــي جرائــم القــات العقوبــات املعمــول بهــا‬\n‫قبــل نفــاذ نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لذلــك كلــه‬\n‫فقــد ثبتــت لــدي إدانــة املدعــى عليــه بحيــازة كميــة القــات املذكــورة‬\n‫أعــاه بقصــد التعاطــي وهــو يســتحق العقوبــة علــى ذلــك يف ضــوء املــادة‬\n‫(‪ )4‬مــن قــرار ســمو زيــر الداخليــة رقــم (‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ‬\n‫املعدلــة بالقــرار الــوزاري رقــم (‪ )3818‬وتاريــخ ‪1410/9/28‬ه ـ ونظــرا‬\n‫لعــدم وجــود ســوابق مســجلة عليــه ولضآلــة مــا ضبــط بحوزتــه ولكــون‬\n‫املضبــوط مــن نبــات القــات واســتصالحا حلالــه فقــد حكمــت عليــه‬\n‫لذلــك بالســجن مــدة شــهر ونصــف تبــدأ مــن تاريــخ القبــض عليــه وإيقافــه‬\n‫علــى ذمــة هــذه القضيــة يف ‪1433/8/19‬ه ـ وإبعــاده إلــى بــاده بعــد‬\n‫انتهــاء محكوميتــه بالســجن ونظــرا ألن املــادة املشــار إليهــا قــد جعلــت‬\n‫التعزيــر باجللــد إلــى نظــر القاضــي فقــد قــررت االكتفــاء عنــه بعقوبــة‬\n‫احلبــس واســتناد ًا إلــى املــادة (‪ )159‬مــن نظــام اإلجــراءات اجلزائيــة فقــد‬\n‫صرفــت النظــر عــن طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه يف‬\n‫ضــوء املــادة الرابعــة مــن قــرار مجلــس الــوزراء رقــم (‪ )11‬لعــام ‪1374‬ه ـ‬\n‫لعــدم دخــول االتهــام املذكــور أعــاه يف منطوقهــا كمــا صرفــت النظــر‬\n‫عــن طلــب املدعــي العــام تشــديد العقوبــة علــى املدعــى عليــه لقــاء اتهامــه‬\n‫بالتســتر علــى مصــدر مــا مت ضبطــه ألن ذلــك مندفــع مبــا علــم مــن حــال‬\n‫بائعــي نبــات القــات يف املنطقــة مــن تخفيهــم وتنكرهــم واســتغاللهم‬\n‫مجهولــي الهويــة لترويــج نبــات القــات وهــو أمــر عمــت بــه البلــوى هــذا‬\n‫مــا ثبــت لــدي وبــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي العــام‬\n‫معارضتــه وطلــب رفعــه حملكمــة االســتئناف دون الئحــة فأجبتــه لذلــك‬\n\n\n                                                                                      ‫‪188‬‬\n\f      ‫وقــرر املدعــى عليــه القناعــة بــه وقــد جــرى النطــق بــه يف متــام الســاعة‬\n      ‫الثانيــة عشــرة وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه أجمعــن حــرر يف ‪1434/2/17‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان برقــم ‪3483829‬‬\n      ‫وتاريــخ‪1434/2/ 25‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪...../‬برقم‪ 3441034‬وتاريــخ ‪1434/2/19‬ه ـ اخلــاص بدعــوى‬\n      ‫املدعــي العــام ضــد ‪-..... /‬مينــي اجلنســية ‪ -‬يف قضيــة ( قــات ) علــى‬\n      ‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n      ‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                     ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪189‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":185,"source_page_end":189,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0ced2f7be85dfdc7541d6ba9a5d563cc9a05ef40eaef06fe85d926ab8bbcd1f1","normalized_text_hash":"32b246c4a1e130434d983f8c62f3292c415726a7178d8030f11a8cf0d9ceacb6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p185-3441034"},{"id":"8f9b957b-9dcc-556d-a2ca-a33f127a4c62","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة -تداخل التعازير -التعزير بالسجن واجللد واملنع من السفر .","document_number":"33416641","case_number":"33577847","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/17","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي وتعاطيها -إقرار- عدم التقيد بالوصف الوارد يف الئحة الدعوى -إدانة -تداخل التعازير -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33416641:‬تاريخه‪1433/09/17:‬هـ‬\n                   ‫رقم الدعوى‪33577847 :‬‬\n      ‫رقم قرار التصديق محكمة االستئناف‪:‬‬\n          ‫‪ 3440166‬تاريخه‪1433/02/18:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي وتعاطيهــا‪ -‬إقــرار‪-‬‬\n‫عــدم التقيــد بالوصــف الــوارد يف الئحــة الدعــوى‪ -‬إدانــة‪ -‬تداخــل‬\n              ‫التعازيــر ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n                       ‫‪ -1‬املادة (‪ )159‬من نظام اإلجراءات اجلزائية‪.‬‬\n‫‪ -2‬املادتان (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد التعاطــي وتعاطيــه لهــا‪ ،‬واحلكــم عليــه‬\n‫بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة وتشــديد العقوبــة بحقــه لقــاء تكــرر ســوابقه‪ ،‬بعــد‬\n‫اســتيقافه قــام بابتــاع حبــوب يشــتبه يف كونهــا محظــورة كانــت يف‬\n‫كيــس بجيبــه وعثــر بالكيــس علــى فتــات مــن احلبــوب‪ ،‬أثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة اإلمفيتامــن‪ ،‬أقــر‬\n‫أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬بنــاء علــى مــا تقــدم‬\n‫حكمــت احملكمــة بإدانــة املدعــى عليــه بجميــع مــا نســب إليــه وقــررت‬\n‫ســجنه ملــدة ســتة أشــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‬\n\n                                                                                   ‫‪190‬‬\n\f      ‫وجلــده ســبعني جلــدة دفعــة واحــدة لقــاء تعاطيــه احلبــوب احملظــورة‬\n      ‫وجلــده ســبعني جلــدة لقــاء الســوابق املســجلة بحقــه‪ ،‬وقنــع املدعــى عليــه‬\n      ‫باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف‬\n                                                          ‫املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة ويف هــذا اليــوم‬\n      ‫الثالثــاء املوافــق ‪1433/9/19‬ه ـ يف متــام الســاعة الواحــدة ظهرا افتتحت‬\n      ‫اجللسة وفيها حضر املدعي العام ‪ ........‬سعودي اجلنسية بالسجل املدني‬\n      ‫رقــم ‪........‬واملعمــد مــن رئيــس هيئــة التحقيــق واالدعــاء العــام برقــم ‪........‬‬\n      ‫ويف ‪1432/6/12‬ه ـ قائــا يف حتريــر دعــواه ضد ‪ ........‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪)..........‬انــه باالطــاع علــى احملضــر املدون‬\n      ‫بتاريــخ ‪1433/8/11‬ه ـ مــن قبــل مركــز هيئــة األمــر باملعــروف والنهــي‬\n      ‫عــن املنكــر بامليقــات املتضمــن انــه مت مالحظــة ســيارة ‪ ........‬وظهــر‬\n      ‫علــى الراكــب إثــر الريبــة ومحاولــة الهــروب ومت اســتيقافه واتضــح أنــه‬\n      ‫بحالــة غيــر طبيعيــة وأخــرج مــن جيبــة األميــن كيســا يشــتبه أن بــه حبوبــا‬\n      ‫محظــورة وقــام بابتالعهــا أمــام مــرأى الفرقــة وعثــر بالكيــس علــى‬\n      ‫فتــات مــن احلبــوب يــزن (‪ )0.2‬اثنــن مــن العشــرة مــن اجلــرام فتــم القبــض‬\n      ‫عليــه‪ .‬وعنــد حضــور املتهــم لالســتجواب تعــذر ذلــك كونــه كان يف‬\n      ‫حالــة ال ميكــن معهــا اســتجوابه ومت بعثــه ملستشــفى الصحــة النفســية‬\n      ‫لعالجــه وتزويدنــا بتقريــر عــن حالتــه‪ .‬وبتاريــخ ‪1433/8/19‬ه ـ مت إعــادة‬\n      ‫اســتجوابه واقــر بقيامــه بابتــاع الكيــس الــذي بــه احلبــوب واقــر بأنــه‬\n\n‫‪191‬‬\n\f‫يعــود لــه بقصــد التعاطــي كمــا اقــر بتعاطيــه الســابق للحبــوب‪ .‬وقــد‬\n‫اثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )........‬لعــام ‪1433‬ه ـ الصــادر‬\n‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية التابــع لــوزارة‬\n‫الصحــة مبنطقــة املدينــة املنــورة إيجابيــة العينــة لإلمفيتامــن احملظــور‬\n‫وهــو مــن املؤثــرات العقليــة اخلاضعــة للرقابــة واملنــوه عنهــا يف اجلــدول‬\n‫الثانــي فئــة (ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫وانتهــى التحقيــق إلــى اتهــام املدعــى عليــه بحيــازة فتــات يــزن (‪)0.2‬‬\n‫اثنــن مــن العشــرة مــن اجلــرام مــن حبــوب اإلمفيتامــن احملظــورة بقصــد‬\n‫التعاطــي وتعاطيــه مــن الكميــة املضبوطــة معــه بابتالعهــا ولنوعهــا مــن‬\n‫الســابق واملجــرم علــى ذلــك وفقــا للمــادة الثالثــة الفقــرة الثانيــة مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م ‪ )39 /‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا‬\n‫جــاء بإقــراره املنــوه عنــه املــدون على الصفحة رقــم (‪ )4‬من دفتر التحقيق‬\n‫املرفــق برقــم (‪ -2 .)20‬مــا ورد مبحضــر القبــض املنــوه عنــه املرفــق لفــه‬\n‫رقــم (‪ -3.)1‬التقريــر الكيميائــي الشــرعي رقــم (‪ 1801‬ك م) املنــوه‬\n‫عنــه املرفــق لفــه (‪ -4.)27‬مــا ورد مبحضــر اثبــات واقعــة عنــد حضــوره‬\n‫لالســتجواب وهــو يف حالــة غيــر طبيعيــة املنــوه عنــه املــدون علــى الصفحة‬\n‫رقــم (‪ )3‬مــن دفتــر التحقيــق املرفــق برقــم (‪ .)20‬وبالبحــث عــن حالتــه‬\n‫اجلنائيــة عثــر لــه علــى ثــاث ســوابق حيــازة واســتعمال مخــدرات وقضيــة‬\n‫اشــتباه وشــرب املســكرات وســرقة مســاكن‪ .‬وحيــث أن مــا أقــدم عليــه‬\n‫املدعــى عليــه فعــل محــرم شــرعا ومعاقــب عليــه نظامــا مبوجــب نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة لــذا أطلــب إثبــات إدانتــه مبــا‬\n‫أســند إليــه واحلكــم عليــه باآلتــي‪ -1 :‬عقوبــة الســجن األصليــة اســتنادا‬\n\n\n                                                                                          ‫‪192‬‬\n\f      ‫للمــادة (‪ )41‬الفقــرة األولــى مــن النظــام املشــار إليــه‪ -2 .‬عقوبــة املنــع‬\n      ‫مــن الســفر خــارج اململكــة التكميليــة اســتنادا للمــادة (‪ )56‬الفقــرة‬\n      ‫(‪ )1‬مــن النظــام املشــار إليــه‪ -3 .‬تشــديد العقوبــة عليــه لقــاء تكــرار‬\n      ‫ســوابقه اســتنادا لتعميــم صاحــب الســمو امللكــي نائــب وزيــر الداخليــة‬\n      ‫رقــم (‪ )93958‬وتاريــخ ‪1429/8/23‬ه ـ هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه صحيــح كلــه‬\n      ‫وانــا نــادم عليــه هكــذا أجــاب وبعــد ســماع الدعــوى واالجابــة املتضمنــة‬\n      ‫مصادقــة املدعــى عليــه علــى دعــوى املدعــي العــام وبعــد االطــاع علــى‬\n      ‫اوراق وطيــات املعاملــة وملــا تقــدم فقــد ثبــت لــدي ادانــة املدعــى عليــه‬\n      ‫مبــا نســب إليــه شــرعا مــن حيازتــه فتــات يــزن (‪ )0.2‬اثنــن مــن العشــرة‬\n      ‫مــن اجلــرام مــن حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي وتعاطيــه‬\n      ‫لنوعهــا مــن الســابق وحكمــت بتعزيــره بســجنه مــدة ســتة أشــهر اعتبــارا‬\n      ‫مــن تاريــخ ايقافــه يف ‪1433/8/19‬ه ـ كمــا حكمــت مبنعــه مــن الســفر‬\n      ‫مــدة ســنتني تبــدأ مــن تاريــخ خروجــه مــن الســجن كمــا حكمــت بجلــده‬\n      ‫ســبعون جلــده لقــاء الســوابق املســجلة بحقــه وبذلــك قضيــت وبعــرض‬\n      ‫احلكــم علــى الطرفــن قــرر املدعــي العــام املعارضــة بــدون الئحــة‬\n      ‫وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة باحلكــم وعلــى ذلــك‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n      ‫وصحبــه وســلم حــرر يف ‪1433/8/19‬هــ‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم‬\n      ‫الثالثــاء املوافــق ‪1433/11/9‬ه ـ الســاعة التاســعة والنصــف افتتحــت‬\n      ‫اجللســة وقــد عــادت املعاملــة إلينــا مــن محكمــة االســتئناف مبكــة‬\n      ‫املكرمــة وبرفقهــا القــرار رقــم ‪ 33432672‬يف ‪1433/10/21‬ه ـ‬\n      ‫املتضمــن مــا نصــه ( وبدراســة احلكــم وصــورة ضبطــه قررنــا إعادتهــا‬\n\n\n‫‪193‬‬\n\f‫لفضيلــة حاكــم القضيــة ملالحظــة أن فضيلتــه لــم يحكــم علــى املدعــى‬\n‫عليــه لقــاء اســتعماله للحبــوب احملظــورة مــع اعترافــه بذلــك إلجــراء‬\n‫مــا يلــزم نحــو مــا أشــير اليــه واهلل املوفــق ) وعليــه أجيــب أصحــاب‬\n‫الفضيلــة قضــاة االســتئناف بــأن املدعــي العــام لــم يطالــب بدعــواه‬\n‫ايقــاع عقوبــة علــى املدعــى عليــه لقــاء تعاطيــه احلبــوب احملظــورة ولــم‬\n‫يــرد يف الئحــة دعــواه مــا يــدل علــى مطالبتــه بذلــك واحلكــم بإيقــاع‬\n‫عقوبــة علــى املدعــى عليــه لــم يطالــب بهــا املدعــي يف غيــر محلــه لــذا‬\n‫فليــس لــدي ســوى مــا حكمــت بــه علــى املدعــى عليــه ولــم يظهــر لــي‬\n‫خالفــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم حــرر يف ‪1433/11/9‬هــ‪ .‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم‬\n‫الثالثــاء املوافــق ‪1434/2/5‬ه ـ الســاعة العاشــرة افتتحــت اجللســة وفيهــا‬\n‫حضــر طــريف الدعــوى وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبكــة املكرمــة وبرفقهــا قــرار املالحظــة رقــم ‪ 33476182‬وتاريــخ‬\n‫‪1433/12/22‬ه ـ مــن الدائــرة اجلزائيــة األولــى واملتضمــن مالحظــة‬\n‫أصحــاب الفضيلــة مــا نصــه( بدارســة احلكــم وصــورة ضبطــه قررنــا‬\n‫إعادتهــا لفضيلــة حاكــم القضيــة ملالحظــة أن مــا أجــاب بــه فضيلتــه‬\n‫غيــر مقنــع فقــد نصــت املــادة التاســعة واخلمســن بعــد املائــة مــن نظــام‬\n‫اإلجــراءات اجلزائيــة علــى أن احملكمــة ال تتقيــد بالوصــف الــوارد يف‬\n‫الئحــة الدعــوى وعليــه أن تعطــى الفعــل الوصــف الــذي يســتحقه ولــو‬\n‫كان مخالفـ ًا للوصــف الــوارد يف الئحــة الدعوى‪...‬الــخ ‪ ،‬فعلــى فضيلتــه‬\n‫إجــراء مــا يلــزم علــى نحــو مــا ذكــر يف قرارنــا الســابق) أ‪.‬ه ـ عليــه ونظر ُا‬\n‫لوجاهــة مــا ذكــره أصحــاب الفضيلــة فقــد حكمــت إضافــة علــى مــا‬\n‫ســبق بحــق املدعــى عليــه بتعزيــره بجلــده ســبعون جلــدة دفعــة واحــده لقــاء‬\n\n\n                                                                                        ‫‪194‬‬\n\f      ‫تعاطيــه احلبــوب احملظــورة التــي أقــر يف مجلــس احلكــم لــدي بتعاطيــه‬\n      ‫لنوعهــا وبذلــك قضيــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه القناعــة باحلكــم وبعرضــه علــى املدعــي العــام قــرر املعارضــة علــى‬\n      ‫احلكــم بــدون الئحــة حــرر يف ‪1434/2/5‬ه ـ وصلــى اهلل وســلم علــى‬\n                                                  ‫نبينــا محمــد والــه وصحبــة وســلم‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بقــرار احملكمــة ومضمونــه املصادقــة علــى احلكــم بعــد االجــراء‬\n      ‫االخيــر وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n‫‪195‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":190,"source_page_end":195,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"724ff835f7f1b903b87f17cd04d1678c77d434c02711e03e92bc0cb71faedc05","normalized_text_hash":"8aa8996f81af6117074ef76789b40ac5c3a598f0bd2f65347e2add3bc3fb98e9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p190-33416641"},{"id":"c1e60f98-7ece-5366-b56a-46b4b30185e6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر- إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن","document_number":"34203698","case_number":"33586086","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/18","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر- إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 34203698 :‬تاريخه ‪33586086 :‬‬\n                  ‫رقم الدعوى‪33586086 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪ 34244108‬تاريخه ‪1434/06/18 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬حــد املســكر‪-‬‬\n‫إقــرار‪ -‬إدانــة‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬التعزيــر بالســجن‬\n                                                                ‫واإلبعــاد ‪.‬‬\n\n\n\n‫‪ -1‬القاعــدة الفقهيــة‪{ :‬املــرء مؤاخــذ بإقــراره}‪ ،‬والقاعــدة الفقهيــة‪:‬‬\n‫{إقــرار اإلنســان علــى نفســه مقبــول}‪ .‬املنثــور مــن القواعــد للزركشــي‬\n‫(‪ )188/1‬واألشــباه والنظائــر للســيوطي (‪ )465/1‬ودرر احلــكام (‪.)79/1‬‬\n‫‪ -2‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة‬\n‫(‪ )2‬مــن املــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة‬\n                                           ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n‫بقصــد التعاطــي وتعاطيــه لــه‪ ،‬واحلكــم عليــه بعقوبــة الســجن واإلبعــاد‬\n‫عــن البــاد طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪،‬‬\n‫وحيــث إنــه مت تفتيــش املدعــى عليــه شــخصي ًا فوجــد يف جيبــه قطعــة‬\n‫مــن احلشــيش املخــدر وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة‬\n‫العينــة املرســلة للحشــيش املخــدر‪ ،‬كمــا أقــر أمــام احملكمــة مبــا‬\n\n                                                                                    ‫‪196‬‬\n\f      ‫أســنده إليــه املدعــي العــام‪ ،‬وحيــث إن املــرء مؤاخــذ بإقــراره وأن إقــرار‬\n      ‫اإلنســان علــى نفســه مقبــول‪ ،‬املدعــى عليــه أبــدى التوبــة وال يوجــد لــه‬\n      ‫ســوابق والكميــة احملــازة قليلــة‪ ،‬فقضــت احملكمــة بإدانــة املدعــى‬\n      ‫عليــه بجميــع مــا نســب إليــه وقــررت جلــده حــد املســكر ثمانــن جلــدة‬\n      ‫دفعــة واحــدة يف مــكان عــام وســجنه ملــدة شــهرين وإبعــاده عــن البــاد‬\n      ‫بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة‬\n                                                                      ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬املــازم القضائــي باحملكمــة‬\n      ‫اجلزائيــة باألحســاء يف املكتــب القضائــي الســادس وبنــاء علــى املعاملــة‬\n      ‫احملالــة مــن رئيــس احملكمــة اجلزائيــة باألحســاء برقــم (‪)33586086‬‬\n      ‫يف ‪1433/9/24‬ه ـ واملقيــدة برقــم (‪ )331749830‬يف ‪1433/9/24‬ه ـ‬\n      ‫وبنــاء علــى تعميــدي مــن فضيلــة الشــيخ‪ .......... /‬رئيــس احملكمــة‬\n      ‫اجلزائيــة باألحســاء املكلــف مبوجــب خطابــه رقــم (‪ )34970436‬يف‬\n      ‫‪1434/4/21‬ه ـ لنظــر القضايــا مــا عــدا الســجناء ويف يــوم األربعــاء‬\n      ‫املوافــق ‪1434/5/1‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة التاســعة‬\n      ‫يف هــذه القضيــة رقــم (‪ )3301700391‬وفيهــا حضــر املدعــي العام ‪........‬‬\n      ‫بالسجل املدني رقم (‪ )........‬وحضر حلضوره املدعى عليه ‪ ........‬مصري‬\n      ‫اجلنســية مبوجــب اإلقامــة الصــادرة مــن الريــاض برقــم (‪ )........‬وبســؤال‬\n      ‫املدعــي العــام عــن دعــواه قــال بصفتــي مدعيــا عامــا بدائرة االدعــاء العام‬\n      ‫مبحافظــة األحســاء أدعــي علــى ‪،........‬البالــغ مــن العمــر(‪ )33‬عام ـ ًا ‪،‬‬\n‫‪197‬‬\n\f‫‪ ........‬مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬محصــن‪،‬‬\n‫متعلــم ‪ ،‬موظــف أهلــي ‪ ،‬قبــض عليــه بتاريخ‪1433/8/21‬ه ـ واليــزال‬\n‫موقــوف مبوجــب امــر االيقــاف رقــم ( ‪ )........‬وتاريخ‪1433/8/22‬ه ـ‬\n‫ومت التمديــد لــه (‪ )25‬يوم ـ ًا ابتــداء مــن ‪1433/8/26‬ه ـ مبوجــب أمــر‬\n‫متديــد رقــم (ه ـ ق ‪ )43196/5/1‬وتاريــخ ‪1433/9/2‬هـ‪ ،‬اســتنادا لبرقية‬\n‫صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر‬\n‫الداخليــة رقــم ( ‪ ) 79425/4/5/1‬وتاريــخ ‪1432/12/20‬ه ـ وأحيــل‬\n‫للســجن العــام انــه بتاريــخ ‪1433/8/21‬ه ـ قبــض عليــه مــن قبــل إحــدى‬\n‫فــرق أمــن الطــرق مبحافظــة األحســاء اثــر اســتيقاف املدعــى عليــه‬\n‫وبرفقــة املدعــو (صــدر بحقــه امــر حفــظ ) وبقيادتــه ســيارة مــن نــوع‬\n‫(‪ )......‬حتمــل اللوحــة رقــم( ‪ ).....‬وبتفتيــش الســيارة بــدت عليــه عالمــات‬\n‫االرتبــاك الشــديد وعنــد تفتيشــهما وجــد يف جيــب املدعــى عليــه علــى‬\n‫قطعــة صغيــرة تــزن (‪/1‬جــم) جــرام يشــتبه انهــا مــن احلشــيش املخــدر‪،‬‬\n‫اثبــت التقريــر الكيميائي الشــرعي رقــم( ‪ )........‬لعام(‪1433‬هـ) ايجابية‬\n‫مــا مت ضبطــه معــه ملــادة احلشــيش املخــدر‪ .‬واملــدرج يف جــدول األول فئــه‬\n‫(أ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبضبــط أقوالــه‪:‬‬\n‫أقــر بصحــة واقعــة القبــض و التفتيــش و بحيازتــه للحشــيش املخــدر‬\n‫لقصــد التعاطــي وتعاطيــه لنوعــه‪ .‬وقــد أســفر التحقيــق عــن توجيــه‬\n‫االتهــام لــه بحيــازة مــا وزنــه (‪)1‬جــرام مــن احلشــيش املخــدر لقصــد‬\n‫التعاطــي وتعاطيــه لنوعــه ‪،‬وذلــك لألدلــة والقرائــن التاليــة‪ 1 :‬ـ إقــراره‬\n‫املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )2-3‬مــن ملــف ســماع االقــوال‬\n‫ملرفــق علــى اللفــة رقــم(‪ 2 .)9‬ـ محضــر القبــض والتفتيــش املرفــق علــى‬\n‫اللفــة رقــم (‪ 3 )6‬ـ التقريــر الكيميائــي الشــرعي املرفــق علــى اللفــة‬\n\n\n                                                                                   ‫‪198‬‬\n\f      ‫رقــم (‪ .)24‬وبالبحــث عمــا إذا كان لــه ســوابق تبــن خلــو ســجله مــن‬\n      ‫الســوابق اجلنائيــة‪ .‬وحيــث أنــه مــا أقــدم عليــه املذكــور وهــو بكامــل‬\n      ‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم و مجــرم ومعاقــب عليــه شــرع ًا‬\n      ‫ونظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم‬\n      ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه مبــا يلــي‪.1 -:‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة ( ‪) 41‬‬\n      ‫مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة لقــاء مــا اســند إليــه‬\n      ‫مــن اتهــام‪.2 .‬بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة ( ‪ ) 56‬مــن‬\n      ‫ذات النظــام وذلــك بإبعــاده خــارج البــاد‪ .‬هــذه دعــواي وبســؤال املدعــى‬\n      ‫عليــه عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام‬\n      ‫مــن قيامــي بحيــازة قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا جــرام (‪1‬جــم)‬\n      ‫لقصــد التعاطــي وتعاطــي لنوعــه فصحيــح وأنــا تائــب إلــى اهلل ونــادم‬\n      ‫علــى مــا بــدر منــي هكــذا أجــاب هــذا فتــم ســؤاله عــن عمــره فقــال‬\n      ‫أبلــغ مــن العمــر ‪ 35‬عامــا هكــذا قــال كمــا مت ســؤاله هــل أنــت متــزوج‬\n      ‫فقــال نعــم هكــذا قــال كمــا مت اطالعــي علــى التقريــر الكيميائــي‬\n      ‫الشــرعي املرفــق يف املعاملــة علــى اللفــة رقــم (‪ )24‬ويتضمــن (إيجابيــة‬\n      ‫قطعــة احلشــيش املخــدر املوصوفــة بالدعــوى) فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بدعــوى املدعــي العــام‬\n      ‫ولكــون هــذا اإلقــرار قــد صــدر مــن مكلــف (عاقــل بالــغ) وللقاعــدة‬\n      ‫الفقهيــة ((أن املــرء مؤاخــذ بإقــراره)) والقاعــدة ((إقــرار اإلنســان علــى‬\n      ‫نفســه مقبــول)) املنثــور مــن القواعــد للزركشــي [ج‪ ]188/1‬واألشــباه‬\n      ‫والنظائــر للســيوطي [ج‪ ]465/1‬ودرر احلــكام [ج‪ ]79/1‬وبعــد االطــاع‬\n\n\n‫‪199‬‬\n\f‫علــى تقريــر الكيميائــي الشــرعي لذلــك كلــه فقــد قــررت مــا يلــي‪:‬‬\n‫أوال‪ :‬ثبــت لــدي تعاطــي املدعــى عليــه للحشــيش املخــدر وقــررت جلــده‬\n‫حــد املســكر ثمانــن جلــدة حــدا دفعــة واحــدة يف مــكان عــام ثانيــا‪:‬‬\n‫ونظــرا لثبــوت حيــازة املدعــى عليــه للحشــيش املخــدر املوصــوف‬\n‫بالدعــوى بقصــد االســتعمال الشــخصي واملتوجــه تعزيــره حســبما نصــت‬\n‫عليــه الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫ونظــرا لكــون الكميــة املضبوطــة مــع املدعــى عليــه قليلــة ولكونــه‬\n‫أبــدى التوبــة والنــدم ولكونــه متــزوج وال يوجــد عليــه ســوابق وهــذه‬\n‫مســوغات معتبــرة يف تخفيــف العقوبــة عنــه وبنــاء علــى الفقــرة األولــى‬\n‫مــن املــادة (‪ )60‬مــن نفــس النظــام فقــد قــررت النــزول عــن أدنــى عقوبــة‬\n‫نــص عليهــا يف الفقــرة األولــى مــن املــادة (‪ )41‬وقــررت تعزيــر املدعــى‬\n‫عليــه بســجنه ملــدة شــهرين محســوبا منهــا مــدة توقيفــه ثالثــا‪ :‬ونظــرا‬\n‫لقيــام املدعــى عليــه بحيــازة احلشــيش املخــدر املوصــوف بالدعــوى‬\n‫وتعاطيــه لنوعــه وهــذه اجلرميتــان نصــت عليهــا الفقــرة الثانيــة مــن املــادة‬\n‫(‪ )3‬مــن نظــام مكافحــة املخــدرات وبنــاء علــى الفقــرة الثانيــة مــن املــادة‬\n‫(‪ )56‬مــن نفــس النظــام فقــد قــررت إبعــاد املدعــى عليــه عــن البــاد‬\n‫بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه‪ ،‬وال يســمح لــه بالعــودة فيمــا‬\n‫عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة ومبــا ســبق كلــه حكمــت‬\n‫وبعرضــه علــى املدعــى عليــه قــرر القناعــة بــه كمــا قــرر املدعــي العــام‬\n‫املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة‬\n‫اعتراضيــة وبذلــك تكــون القضيــة منتهيــة وقــررت بعــث كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف بالشــرقية لتدقيــق احلكــم حســب املتبــع‬\n‫وبــاهلل التوفيــق واختتمــت اجللســة يف متــام الســاعة التاســعة والنصــف‬\n\n\n                                                                                      ‫‪200‬‬\n\f      ‫وللبيــان حــرر يف ‪1434/5/1‬ه ـ ـ وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                   ‫وصحبــه وســلم تســليما كثيــرا‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم الســبت املوافق‪1434/7/8‬ه ـ افتتحــت‬\n      ‫اجللســة يف هــذه الدعــوى املقدمــة مــن املدعــي العــام ضــد‪ ........‬يف قضيــة‬\n      ‫مخــدرات وبنــاء علــى رجــوع املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية مبوجــب خطابهــم رقــم (‪ )34/1249845‬يف ‪1434/6/25‬ه ـ‬\n      ‫وبرفقــه القــرار الصــادر مــن الدائــرة اجلزائيــة الثالثيــة األولــى ‪ -‬ج‪1/‬‬\n      ‫برقــم (‪ )34244108‬وتاريــخ ‪1434/6/18‬ه ـ ونــص احلاجــة منــه‬\n      ‫(وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن فضيلــة‬\n      ‫ناظــر القضيــة مــازم قضائــي والقضيــة بهــا ســجني فمــا وجــه مســتند‬\n      ‫فضيلتــه يف نظــر القضيــة واهلل املوفق)أ‪.‬ه ـ عليــه توقيــع وختــم أصحــاب‬\n      ‫الفضيلــة كل مــن قاضــي اســتئناف ‪ ، ........‬قاضــي اســتئناف ‪،........‬‬\n      ‫رئيــس الدائــرة ‪ ........‬بالنســبة للمالحظــة فمــا ذكــره أصحــاب الفضيلــة‬\n      ‫‪ -‬وفقهــم اهلل ‪ -‬مــن أن املــازم القضائــي ال ينظــر قضايــا الســجناء‬\n      ‫واملوقوفــن صحيــح وهــذا مــا نــص عليــه يف الفقــرة (و) مــن البنــد ثانيــا‬\n      ‫مــن املــادة الثامنــة مــن تنظيــم أعمــال املالزمــن القضائيــن ولكــن‬\n      ‫املدعــى عليــه لــم يكــن ســجينا قبــل نظرنــا للقضيــة بــل كان مفرجــا‬\n      ‫عنــه حيــث إنــه كان موقوفــا فأطلــق ســراحه كمــا هــو مبــن يف أوراق‬\n      ‫املعاملــة علــى اللفــة رقــم (‪ )47-42-41‬ثــم بعــد مضــي مــدة مــن اإلفــراج‬\n      ‫عــن املدعــى عليــه جــررت الكتابــة بعدهــا مــن فضيلــة الشــيخ‪........ /‬‬\n      ‫‪-‬ســلمه اهلل ‪ -‬لســعادة مديــر مكافحــة املخــدرات مبحافظــة األحســاء‬\n      ‫مبوجــب خطابــه رقــم (‪ )33/2077650‬يف ‪1434/1/28‬ه ـ إلبــاغ‬\n      ‫املدعــى عليــه مبوعــد جلســته ثــم ألفــى اجلــواب مبوجــب خطابهــم رقــم‬\n\n\n‫‪201‬‬\n\f‫(‪ )........‬يف ‪1434/4/29‬ه ـ املرفــق يف املعاملــة علــى اللفــة رقــم (‪)47‬‬\n‫ويتضمــن إبــاغ املدعــى عليــه مبوعــد جلســته وهــو يــوم األربعــاء املوافــق‬\n‫‪1434/5/1‬ه ـ فحضــر املدعــى عليــه يف املوعــد املذكــور آنف ـ ًا ولــم‬\n‫يكــن ســجينا‪ .‬فــإذا فــإن املدعــى عليــه لــم يكــن ســجينا كمــا ذكــر‬\n‫أصحــاب الفضيلــة ‪ -‬وفقهــم اهلل ‪ -‬وإمنــا مفــرج عنــه واملــادة املذكــورة‬\n‫بعاليــه إمنــا نصــت علــى أن املــازم القضائــي ممنــوع مــن نظــر دعــوى مــن‬\n‫كان ســجينا أو موقوفــا فعليــا وأحضــر إلــى مجلــس احلكــم ونظــرت‬\n‫دعــواه وهــو علــى تلــك الصفــة وهــذا ال يتحقــق يف املدعــى عليــه حيــث إنــه‬\n‫كان مفرجــا عنــه وال زال لــذا فلــم يظهــر لــي مــا يؤثــر علــى مــا حكمــت‬\n‫بــه واهلل ولــي التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                     ‫وســلم حرر‪1434/7/8‬هـ ــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي انــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة‬\n‫باالحســاء يف املكتــب الســادس ففــي يــوم األربعــاء املوافــق ‪1434/9/2‬‬\n‫افتتحــت اجللســة يف هــذه الدعــوى املقدمــة من املدعي العام ضــد‪.............‬‬\n‫يف قضيــة مخــدرات وبنــاء علــى رجــوع املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية مبوجــب خطابهــم رقــم (‪ )34/1928542‬يف‬\n‫‪1434/8/24‬ه ـ وبرفقــة القــرار الصــادر مــن الدائــرة اجلزائيــة الثالثيــة‬\n‫االولــى ج‪ 1/‬برقــم (‪ )34299191‬وتاريــخ ‪1434/8/16‬ه ـ ونصــه بعــد‬\n‫املقدمــة (وبدراســة القــرار وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‬\n‫‪ 34244108‬يف ‪ 1434/6/18‬ه ـ قررنــا املصادقــة علــى احلكــم بعــد‬\n‫اإليضــاح االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                      ‫وصحبــه وســلم حــرر ‪ 1434/9/2‬ه ـ )‪.‬‬\n\n\n\n                                                                                     ‫‪202‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":196,"source_page_end":202,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6926e6989252e4eb29fa955f77a37988a986721210cbf671f3226d1a96a72a96","normalized_text_hash":"ce34d441812e3496d0eedf83087e704791bfe03500c79e3dd8e11d00781ed138","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p196-34203698"},{"id":"27f4bf48-d66e-5d0c-bbb5-a7709b544faa","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -دخول التعزير يف احلد -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واإلبعاد .","document_number":"33467443","case_number":"33622809","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/24","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه -حد املسكر -دخول التعزير يف احلد -إقرار -إدانة -نزول عن احلد األدنى للعقوبة -التعزير بالسجن واإلبعاد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33467443:‬تاريخه ‪1433/10/24:‬هـ‬\n                         ‫رقم الدعوى ‪33622809:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3419729‬تاريخه‪1434/01/21:‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه‪ -‬حــد املســكر‬\n      ‫‪ -‬دخــول التعزيــر يف احلــد ‪ -‬إقــرار‪ -‬إدانــة‪ -‬نــزول عــن احلــد األدنــى‬\n                                     ‫للعقوبــة ‪ -‬التعزيــر بالســجن واإلبعــاد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول اهلل تعالــى‪ (( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر‪..‬‬\n                                                                                 ‫اآليــة))‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر‬\n                                                                 ‫حــرام )‪.‬رواه مســلم‪.‬‬\n      ‫‪ -3‬جــاء يف الشــرح املمتــع (‪« :)293/14‬أن الصحابــة رضــي اهلل عنهــم ملــا‬\n                                                                      ‫تشــاوروا‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -4‬جــاء يف كشــاف القنــاع (‪« :)112/14‬أن علي ـ ًا أتــي بالنجاشــي قــد‬\n                                                                ‫شــرب خمــر ًا‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -5‬جــاء يف اإلنصــاف (‪« :)438/8‬وأبــو العبــاس يــرى أن حكمهــا حكــم‬\n                                                                     ‫الشــراب‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -6‬قــول شــيخ اإلســام رحمــه اهلل يف مجمــوع الفتــاوى (‪:)198/34‬‬\n      ‫«وكذلــك احلشيشــة املســكرة يجــب فيهــا احلــد‪ ..‬إلــخ»‪ .‬وقولــه‬\n                         ‫(‪« :)214/34‬الصحيــح أن احلشيشــة مســكرة‪ ..‬إلــخ»‪.‬‬\n      ‫‪ -7‬جــاء يف فتــح البــاري (‪« :)45/10‬واســتدل مبطلــق قولــه صلــى اهلل‬\n               ‫عليــه وســلم‪( :‬كل مســكر حــرام) علــى حتــرمي مــا يســكر‪ ..‬إلــخ»‪.‬‬\n‫‪203‬‬\n\f‫‪ -8‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬والفقــرة (‪ )2‬مــن املــادة (‪ )56‬والفقــرة (‪)1‬‬\n        ‫مــن املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫‪ -9‬قــرار هيئــة كبــار العلمــاء رقــم (‪ )53‬وتاريــخ ‪1397/4/4‬ه ـ الــذي‬\n‫تضمــن بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع كمــا‬\n                                                   ‫قــرر أنــه ثمانــون جلــدة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش‬\n‫املخــدر بقصــد التعاطــي وتعاطيــه لــه‪ ،‬حيــث إنــه مت تفتيــش الســيارة‬\n‫التــي يقودهــا املدعــى عليــه بعــد توفــر معلومــات عــن حيازتــه للحشــيش‬\n‫املخــدر فعثــر فيهــا علــى قطعــة مــن احلشــيش املخــدر‪ ،‬وأثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة احلشــيش املخــدر‪،‬‬\n‫كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬وحيــث‬\n‫إن احلشــيش مســكر وأنــه يقــام حــد املســكر علــى متعاطيــه‪ ،‬كمــا‬\n‫أنــه يجــوز اجلمــع بــن احلــد والتعزيــر فقضــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بجميــع مــا نســب إليــه وقــررت إقامــة حــد املســكر عليــه بجلــده‬\n‫ثمانــن جلــدة دفعــة واحــدة يف مــكان عــام وســجنه ملــدة شــهرين ومنعــه‬\n‫مــن الســفر خــارج اململكــة مــدة ســنتني‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n‫وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                               ‫علــى احلكــم‪.‬‬\n\n\n\n\n                                                                                    ‫‪204‬‬\n\f      ‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا القاضــي باحملكمــة اجلزائيــة بالدمــام ففــي يــوم الســبت املوافــق‬\n      ‫‪14 33/11/13‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباحــا وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن هيئــة التحقيــق واالدعــاء العــام برقــم ‪49936‬‬\n      ‫وتاريــخ ‪ 1433/10/22‬ه ـ واملقيــدة بــوارد مكتبنــا برقــم ‪33188838‬‬\n      ‫وتاريخ‪1433/10/24‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪........‬ضــد‬\n      ‫املدعــى عليــه ‪ ........‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪........‬‬\n      ‫وباالطــاع علــى محضــر واقعــة القبــض والضبــط والتفتيــش املعــد مــن‬\n      ‫رجــال مكافحــة املخــدرات بالدمــام تبــن أنــه يف يــوم الســبت املوافــق‬\n      ‫‪1433/9/23‬ه ـ توفــرت معلومــات عــن شــخص يدعــى ‪ ...........‬مــن احــد‬\n      ‫املصــادر انــه يحتــاز كميــة مــن احلشــيش املخــدر بحــي ‪........‬بالدمــام‬\n      ‫ومبراقبتــه شــوهدت ســيارة مــن نــوع ‪ .......‬يســتقلها شــخص ينطبــق عليــه‬\n      ‫الوصــف وبعــد وقوفــه عنــد إحــدى البقــاالت مت اســتيقافه وبتفتيشــه‬\n      ‫وتفتيــش ســيارته عثــر علــى قطعــة ذات لــون اســود تــزن جميعهــا (‪)9.9‬‬\n      ‫تســعة جرامات وتســعة من العشــرة من اجلرام يشــتبه أن تكون حشــيش‬\n      ‫مخــدر داخــل درج الســيارة وبالتأكــد مــن هويتــه اتضــح انــه وأثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬يف ‪1433/10/3‬ه ـ إيجابيــة‬\n      ‫العينــة مــن املــادة املضبوطــة للحشــيش املخــدر‪ .‬وقــد انتهــى التحقيــق إلــى‬\n      ‫اتهــام‪ /‬باالتي‪-1/‬حيازتــه قطعــة تــزن (‪ )9.9‬تســعة جرامــات وتســعة‬\n      ‫مــن العشــرة مــن احلشــيش املخــدر لقصــد التعاطــي ‪-2‬تعاطــي احلشــيش‬\n      ‫املخــدر وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬محضــر القبــض والضبــط‬\n\n‫‪205‬‬\n\f‫والتفتيــش املــدون علــى الصفحتــن رقــم ( ‪ )2‬و(‪)11‬مــن ملــف إجــراءات‬\n‫االســتدالل لفــة رقــم (‪ -2)1‬اعترافــه حتقيقــا مبــا اســند إليــه املــدون على‬\n‫الصفحــة رقــم (‪ ) 19-18‬مــن ملــف إجــراءات االســتدالل لفــة رقــم (‪-3)1‬‬\n‫التقريــر الكيمــاوي الشــرعي املرفــق علــى اللفــة رقــم (‪ .)14‬وحيــث إن‬\n‫مــا أقــدم عليــه املذكــور‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل‬\n‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات مــا أســند إليــه وفقـ ًا‬\n‫للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واحلكــم‬\n‫عليــه مبــا يلي‪-1:‬بعقوبــة الســجن الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪)41‬‬\n‫مــن نظــام مكافحــة املخــدرات ‪-2‬إبعــاده عــن البــاد وفق ـ ًا للفقــرة (‪)2‬‬\n‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‪ .‬هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام أننــي قمــت‬\n‫بحيــازة قطعــة حشــيش بلــغ وزنهــا (‪ )9.9‬تســعة جرامــات وتســعة مــن‬\n‫العشــرة مــن احلشــيش بقصــد التعاطــي وأننــي أتعاطــى احلشــيش املخــدر‬\n‫كل ذلــك صحيــح هكــذا أجــاب وقــد جــرى اطالعــي علــى أوراق‬\n‫املعاملــة كمــا جــرى اطالعــي علــى التقريــر الكيمــاوي الشــرعي رقــم‬\n‫‪........‬وتاريــخ ‪1433/10/3‬ه ـ املرفــق باملعاملــة رقــم ( ‪ )15-14‬واملتضمــن‬\n‫ثبــوت إيجابيــة املضبــوط ملــادة احلشــيش املخــدر كمــا جــرى منــا االطالع‬\n‫علــى صحيفــة ســوابق املدعــى عليــه فوجــدت خاليــة فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ونظــرا ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه‬\n‫أعــاه وبعــد االطــاع علــى أوراق‪ .‬املعاملــة ودراســتها ونظــرا ملصادقــة‬\n‫املدعــى عليــه للتهمــة املنســوبة إليــه مــن قبــل املدعــي العــام‪ .‬ونظــرا إلــى‬\n‫أن مــا قــام بــه املدعــى عليــه هــو محــرم شــرعا ومجــرم نظامــا ونظــرا‬\n‫إلــى أن تعاطــي احلشــيش املخــدر يــؤدي إلــى اإلســكار‪ ،‬وقــد نــص أهــل‬\n\n\n                                                                                        ‫‪206‬‬\n\f      ‫العلــم علــى إقامــة احلــد علــى متنــاول احلشــيش كمــا ذكــر املــرداوي يف‬\n      ‫اإلنصــاف يف (‪ )438/8‬حيــث قــال‪« :‬وأبــو العبــاس يــرى أن حكمهــا‬\n      ‫حكــم الشــراب املســكر يف إيجــاب احلــد وهــو الصحيــح إن أســكرت‬\n      ‫أو كثيرهــا وإال حرمــت وعــزر فقــط» وقــال شــيخ اإلســام‪« :‬وكذلــك‬\n      ‫احلشيشــة املســكرة يجــب فيهــا احلــد ومــن ظــن أن احلشيشــة ال تســكر‬\n      ‫وإمنــا تغيــب العقــل بــا لــذة فلم يعــرف حقيقة أمرهــا» (‪ ،)198/34‬وقال‪:‬‬\n      ‫«الصحيــح أن احلشيشــة مســكرة كالشــراب» الفتــاوى (‪)214/34‬‬\n      ‫قــال ابــن حجــر‪« :‬واســتدل مبطلــق قولــه صلــى اهلل عليــه وســلم‪( :‬كل‬\n      ‫مســكر حــرام) علــى حتــرمي مــا يســكر ولــو لــم يكــن شــرابا فيدخــل‬\n      ‫يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي وغيــره بأنهــا مســكرة»‬\n      ‫فتــح البــاري (‪ )45/10‬واهلل تعالــى يقــول‪ ( :‬يــا أيهــا الذيــن آمنــوا إمنــا‬\n      ‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n      ‫لعلكــم تفلحــون ) ولقولــه صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر‬\n      ‫وكل خمــر حــرام )رواه مســلم «وألن الصحابــة ـ رضــي اهلل عنهــم ملــا‬\n      ‫تشــاوروا يف عهــد عمــر رضــي اهلل عنــه حــن أكثــر النــاس مــن شــربه‪،‬‬\n      ‫قــال عبــد الرحمــن بــن عــوف رضــي اهلل عنــه‪ :‬أخــف احلــدود ثمانــون‬\n      ‫فوافــق علــى ذلــك الصحابــة» أ‪.‬ه ـ الشــرح املمتــع (‪ )293/14‬واســتناد ًا‬\n      ‫لقــرار هيئــة كبــار العلمــاء رقــم ‪ 53‬وتاريــخ ‪1397/4/4‬ه ـ والــذي‬\n      ‫تضمــن بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع كمــا قــرر‬\n      ‫أنــه ثمانــون جلــدة ‪.‬أ‪.‬ه ـ وألنــه يســوغ اجلمــع بــن احلــد والتعزيــر إذا وجــد‬\n      ‫جنايتــن ملــا روى أحمــد بإســناده أن عليـ ًا أتــي بالنجاشــي قد شــرب خمر ًا‬\n      ‫يف رمضــان فجلــده ثمانــن احلــد وعشــرين ســوط ًا لفطــره يف رمضــان‬\n      ‫وأخرجــه أيضـ ًا عبدالــرزاق وابــن أبــي شــيبة والبيهقــي (كشــاف القنــاع‬\n\n\n‫‪207‬‬\n\f‫‪ )112/14‬وبنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة ونظــرا خللــو ســجل املدعــى عليــه‬\n‫مــن الســوابق ونظــرا لقلــة الكميــة ونظــرا ملــا ظهر لي مــن أخالق املدعى‬\n‫عليــه ونظــرا إلــى أن مصيــر األجنبــي اإلبعــاد وبنــاء علــى الفقــرة رقــم (‪)1‬‬\n‫مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫والتــي تقتضــي النــزول عــن احلــد األدنــى مــن عقوبــة الســجن املنصــوص‬\n‫عليهــا يف املــادة (احلاديــة واألربعــن) ولــكل مــا ســبق‪( :‬أوالً)‪ :‬ثبــت لــدي‬\n‫إدانــة املدعــى عليــه مبــا نســب إليــه مــن حيازتــه قطعــة بلــغ وزنهــا تســعة‬\n‫جرامــات وتســعة مــن العشــرة مــن احلشــيش املخــدر بقصــد التعاطــي‬\n‫وبذلــك حكمــت وحكمــت علــى املدعــى عليــه لقــاء ذلــك مبــا يلــي‪)1( :‬‬\n‫حكمــت علــى املدعــى عليــه بســجنه شــهرين يحتســب منهــا مــا أمضــاه‬\n‫موقوفــا يف هــذه القضيــة وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n‫(‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ووفق ـ ًا للفقــرة‬\n‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة‪)2( .‬حكمــت علــى املدعــى عليــه بإبعــاده عــن اململكــة بعــد‬\n‫تنفيــذ العقوبــة احملكــوم بهــا عليــه وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n‫(‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقلية‪(.‬ثانياً)‪:‬ثبــت‬\n‫لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن تعاطيــه للحشــيش املخــدر‬\n‫وبذلــك حكمــت للحــق العــام وحكمــت علــى املدعــى عليــه لقــاء ذلــك‬\n‫حــدا بجلــده ثمانــن جلــدة دفعــة واحــدة يف مــكان عــام إقامــة حلــد‬\n‫املســكر عليــه‪ .‬وبعــرض احلكــم علــى الطرفــن قنــع املدعــى عليــه أمــا‬\n‫املدعــي العــام فقــرر االعتــراض مكتفيــا مبــا يف أوراق املعاملــة وأغلقــت‬\n‫اجللســة الســاعة العاشــرة والربــع صباحــا وعلــى ذلــك جــرى التوقيــع‬\n\n\n                                                                                         ‫‪208‬‬\n\f      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1433/11/13‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي يوم‬\n      ‫األربعــاء املوافــق ‪14 34/02/13‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n      ‫صباحــا وفيهــا عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية بخطــاب رئيــس محكمــة االســتئناف رقــم ‪34/109244‬‬\n      ‫وتاريــخ ‪1434/02/5‬ه ـ وبرفقهــا القــرار رقــم ‪ 3419729‬وتاريــخ‬\n      ‫‪1434/01/21‬ه ـ الصــادر مــن قضــاة الدائــرة اجلزائيــة الثانيــة وهــم‬\n      ‫فضيلــة الشــيخ‪ ......../‬وفضيلــة الشــيخ‪ ......../‬وفضيلــة الشــيخ‪......../‬‬\n      ‫واملتضمــن املصادقــة علــى احلكــم وللمعلوميــة فقــد جــرى حتريــره‬\n      ‫وختمــت يف الســاعة العاشــرة والنصــف صباح ـ ًا وبــاهلل التوفيــق وصلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف‬\n                                                                ‫‪1434/02/13‬هــ‪.‬‬\n\n\n\n\n‫‪209‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":203,"source_page_end":209,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8f40d59d94513705ca90602e02b5682a7ef496abfbe7f93efcfcd501db992256","normalized_text_hash":"f24830cb2bdd8608d623a1b17995264e6b3cb914d63f737190f584d8777e027b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p203-33467443"},{"id":"f15967d5-f687-5ebb-a1ac-ec72826b6d67","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة هيروين بقصد التعاطي وتعاطيه -إقرار -إدانة- تشديد العقوبة -التعزير بالسجن واجللد واملنع من السفر .","document_number":"3413519","case_number":"33627341","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/17","year":"1434","subject":"مخدرات -حيازة هيروين بقصد التعاطي وتعاطيه -إقرار -إدانة- تشديد العقوبة -التعزير بالسجن واجللد واملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3413519 :‬تاريخه‪1434/01/17 :‬هـ‬\n                   ‫رقم الدعوى‪33627341:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪34248054‬تاريخه‪1434/06/21:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة هيرويــن بقصــد التعاطــي وتعاطيــه‪ -‬إقــرار‪ -‬إدانــة‪-‬‬\n     ‫تشــديد العقوبــة ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪.‬‬\n\n\n\n\n       ‫املواد (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة الهيرويــن بقصــد التعاطــي وتعاطيــه منــه ‪ ،‬واحلكــم عليــه‬\n‫بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة‪ .‬وحيــث إنــه قــد مت تفتيــش الســيارة التــي يقودهــا‬\n‫املدعــى عليــه واالشــتباه بهــا فعثــر فيهــا علــى الهيرويــن‪ ،‬وأقــر املدعــى‬\n‫عليــه أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام وأعلــن توبتــه‪،‬‬\n‫وملــا كان املدعــى عليــه مــن أربــاب الســوابق فقضــت احملكمــة بإدانــة‬\n‫املدعــى عليــه بجميــع مــا نســب إليــه وقــررت جلــده ثمانــن جلــدة دفعــة‬\n‫واحــدة حــد املســكر وســجنه ملــدة ســنة وشــهرين ومنعــه مــن الســفر‬\n‫خــارج اململكــة ملــدة ســنتني وجلــده مائــة جلــدة علــى دفعتــن لقــاء تعــدد‬\n‫ســوابقه وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‬\n                   ‫وقــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n                                                                                    ‫‪210‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 33627341‬وتاريــخ‬\n      ‫‪1433/10/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331906418‬وتاريــخ‬\n      ‫‪1433/10/28‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1433/12/29‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 :30‬وفيهــا حضــر املدعــي العــام املــدون خطــاب‬\n      ‫تعميــده يف قضايــا ســابقة وادعــى علــى احلاضــر معــه باملجلــس الشــرعي‬\n      ‫‪ ........‬ســعودي اجلنســية ســجل مدنــي رقــم ‪ ........‬قائــا يف دعــواه‬\n      ‫‪1433/10/11‬ه ـ مت القبــض علــى املدعــى عليــه قبــل إحــدى فــرق إدارة‬\n      ‫مكافحــة املخــدرات مبكــة املكرمــة لــورود معلومــات مــن أحــد‬\n      ‫مصادرهــم الســرية بــأن مجموعــة مــن األشــخاص يقومــون بتعاطــي‬\n      ‫الهيرويــن املخــدر بحــي ‪ ........‬وبانتقــال الفرقــة للحــي املشــار إليــه مت‬\n      ‫االشــتباه بســيارة كان يقودهــا املدعــى عليــه ويرافقــه شــخص آخــر‬\n      ‫(أطلــق ســراحه وحفــظ االتهــام بحقــه مــن قبــل جهــة التحقيــق لعــدم‬\n      ‫كفايــة االدلــة) وباســتيقافهما وتفتيشــهما ضبــط يف الســيارة مبقعــد‬\n      ‫املدعــى عليــه (بــن املقعــدة و ناقــل الســيارة ( القيــر )) كيــس بــه مــادة‬\n      ‫صفــراء اللــون بلــغ وزنهــا ( ‪2‬جــم ) جرامــن وقــد انتهــى التحقيــق معــه‬\n      ‫الــى اتهامــه بحيــازة كيــس بــه مــادة الهرويــن املخــدر بلــغ وزنــه ( ‪2‬جــم )‬\n      ‫جرامــن بقصــد التعاطــي وتعاطيــه للهيرويــن املخــدر يف الســابق وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة‪ -1 :‬إقــراره ‪ -2‬محضــري البــاغ والضبــط‬\n      ‫‪ -3‬التقريــر الكيميائــي الشــرعي لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n\n‫‪211‬‬\n\f‫إليــه واحلكــم عليــه مبــا يلــي‪1:‬ـ بالســجن وفقــا للمــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات‪ .2.‬منعــه مــن الســفر خلــارج البــاد بعــد انتهــاء تنفيذ‬\n‫عقوبتــه وفقــا للمــادة (‪ )56‬مــن نفــس النظــام‪3‬ـ التشــديد عليــه لكثــرة‬\n‫ســوابقه هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائــا مــا ذكــره‬\n‫املدعــي العــام صحيــح جملــة وتفصيــا وكانــت آخــر مــرة تعاطيــت فيهــا‬\n‫الهيرويــن قبــل أربــع ســنوات وأنــا تائــب إلــى اهلل عــز وجــل هــذا مــا لــدي‬\n‫وباالطــاع علــى املعاملــة وجــدت بــن طياتهــا علــى لفــة رقــم ‪ 28‬صحيفــة‬\n‫ســوابق املدعــى عليــه املتضمنــة وجــود ثــاث عشــرة ســابقة عليــه منهــا‬\n‫ثمــان حيــازة واســتعمال مخــدرات أو احداهمــا علــى مــا هــو مفصــل يف‬\n‫الصحيفــة فبنــاء علــى مــا ســبق مــن الدعــوى واالجابــة ومبــا أن االتهــام‬\n‫توجــه للمدعــى عليــه بحيــازة كيــس بــه مــادة الهيرويــن املخــدر بلــغ‬\n‫وزنــه جرامــن بقصــد التعاطــي وتعاطيــه لــذات النــوع يف الســابق ومبــا‬\n‫أن املدعــى عليــه أقــر مبــا اتهــم بــه ومبــا أن املدعــى عليــه ســوابق مــن‬\n‫جنــس هــذه القضيــة لذلــك فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة‬\n‫كيــس بــه مــادة الهيرويــن يــزن جرامــن بقصــد التعاطــي وتعاطيــه‬\n‫لــذات النــوع يف الســابق وحكمــت بجلــده ثمانــن جلــدة دفعــة واحــدة‬\n‫حــد املســكر لقــاء تعاطيــه للهيرويــن وســجنه ثمانيــة أشــهر حتتســب‬\n‫مــن تاريــخ إيقافــه لقــاء إدانتــه باحليــازة ولقــاء تعــدد ســوابقه ومنعــه مــن‬\n‫الســفر ملــدة ســنتني بعــد انتهــاء تنفيــذ عقوبتــه مــع التأكــد مــن عــدم‬\n‫تنفيــذ حــد املســكر علــى املدعــى عليــه خــال الســنوات األربــع املاضيــة‬\n‫وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي‬\n‫العــام االعتــراض بالئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/12/29‬ه ـ احلمــد‬\n\n\n                                                                                        ‫‪212‬‬\n\f      ‫هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق‪ 1434/05/13‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة احلاديــة عشــر وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وقــاد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n      ‫برقــم ‪ 331906418‬يف ‪1434/4/24‬ه ـ وبرفقهــا قــرار الدائــرة اجلزائيــة‬\n      ‫اخلامســة رقــم ‪ 34193445‬يف ‪1434/4/21‬ه ـ متضمنــا بعــد املقدمــة‬\n      ‫مــا نصــه وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر‬\n      ‫إعادتهــا لفضيلــة حاكمهــا ملالحظــة أن العقوبــة قليلــة جــدا لكثــرة‬\n      ‫ســوابقه فالبــد مــن عقوبــة زاجــرة رادعــة واهلل املوفــق عليــه أشــكر‬\n      ‫أصحــاب الفضيلــة ولوجاهــة مــا ذكــروه فقــد حكمــت إضافــة إلــى‬\n      ‫مــا ســبق بســجنه أربعــة أشــهر إضافيــة وجلــده مائــة جلــدة مفرقــة علــى‬\n      ‫دفعتــن متســاويتني بينهمــا أســبوع لقــاء تعــدد ســوابقه وبعرضــه علــى‬\n      ‫الطرفــن قــرر املدعــي العــام بقــاءه علــى االعتــراض وقــرر املدعــى‬\n      ‫عليــه القناعــة وبــه ختمــت اجللســة الســاعة احلاديــة عشــر والربــع وبــاهلل‬\n      ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                           ‫يف ‪ 1434/05/13‬ه ـ ‪.‬‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جرى منا نحن قضاة الدائرة اجلزائية اخلامســة مبحكمة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الواردة مــن فضيلة رئيس‬\n      ‫احملكمة مبكة املكرمة برقم ‪ 341079292‬وتاريخ ‪ 1434/6/11‬هـ‬\n      ‫املرفــق بهــا القــرار رقــم ‪ 3413519‬وتاريــخ ‪ 1434/1/17‬ه ـ الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ......... /‬القاضــي باحلكمــة اجلزائيــة مبكــة املكرمــة‬\n      ‫املتضمــن دعــوى املدعــي العــام ضــد ‪ ....... /‬ســعودي اجلنســية املتهــم يف‬\n      ‫مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n\n‫‪213‬‬\n\f‫ضبطــه قررنــا املوافقــة علــى احلكــم بعــد االجــراء االخيــر ‪ ،‬واهلل املوفــق‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪214‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":210,"source_page_end":214,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"69245ffe9fc208a7f7cdd02a429252bb623e5428418e919aff3bc6c9fa24d883","normalized_text_hash":"03890e7c7b22420ddad56f3fcff18a4d5fdc38d919401687d67ed4256c99ea57","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p210-3413519"}]$archive_payload$::jsonb) AS x LIMIT 25
